import { contentHash, PoaError } from '@poa/domain';
import {
  AccountingReceipt,
  PortfolioValuation,
  PositionValuationInput,
  ShadowPortfolio,
  type AccountingCostData,
  type AccountingReceiptData,
  type PortfolioValuationData,
  type PositionValuationInputData,
  type ShadowPortfolioData,
} from '@poa/schemas';

const UINT256_LIMIT = 1n << 256n;
const UINT_PATTERN = /^(0|[1-9][0-9]{0,77})$/;
const by =
  <T>(key: (value: T) => string) =>
  (a: T, b: T) =>
    key(a).localeCompare(key(b));
const uint = (value: string) => {
  if (!UINT_PATTERN.test(value)) fail(`Invalid canonical uint: ${value}`);
  const parsed = BigInt(value);
  if (parsed >= UINT256_LIMIT) fail(`Canonical uint exceeds uint256: ${value}`);
  return parsed;
};
const text = (value: bigint) => value.toString();
const total = (values: readonly string[]) =>
  values.reduce((sum, value) => sum + uint(value), 0n);
function fail(message: string): never {
  throw new PoaError('ACCOUNTING_INVARIANT', message);
}
function transition(message: string): never {
  throw new PoaError('INVALID_TRANSITION', message);
}
function requireUInt(value: bigint, label: string) {
  if (value < 0n || value >= UINT256_LIMIT) fail(`${label} is outside uint256`);
  return value;
}
function unique<T>(
  items: readonly T[],
  key: (value: T) => string,
  label: string,
) {
  if (new Set(items.map(key)).size !== items.length) fail(`Duplicate ${label}`);
}

export interface ScaleResult {
  valueMinor: string;
  remainder: {
    kind: 'EXACT' | 'DISCARDED' | 'ADDED';
    amountSourceMinor: string;
    denominator: string;
  };
}

export function mulDiv(
  multiplicand: string,
  multiplier: string,
  denominator: string,
  rounding: 'FLOOR' | 'CEIL',
): ScaleResult {
  const a = uint(multiplicand);
  const b = uint(multiplier);
  const d = uint(denominator);
  if (d === 0n) fail('Division denominator must be positive');
  const product = a * b;
  const quotient = product / d;
  const remainder = product % d;
  const rounded =
    rounding === 'CEIL' && remainder !== 0n ? quotient + 1n : quotient;
  requireUInt(rounded, 'Rounded result');
  return {
    valueMinor: text(rounded),
    remainder: {
      kind:
        remainder === 0n
          ? 'EXACT'
          : rounding === 'FLOOR'
            ? 'DISCARDED'
            : 'ADDED',
      amountSourceMinor: text(
        remainder === 0n || rounding === 'FLOOR' ? remainder : d - remainder,
      ),
      denominator: text(d),
    },
  };
}

export function rescaleMinor(
  amountMinor: string,
  fromDecimals: number,
  toDecimals: number,
  rounding: 'FLOOR' | 'CEIL',
): ScaleResult {
  if (!Number.isInteger(fromDecimals) || !Number.isInteger(toDecimals))
    fail('Decimal scales must be integers');
  if (
    fromDecimals < 0 ||
    toDecimals < 0 ||
    fromDecimals > 36 ||
    toDecimals > 36
  )
    fail('Decimal scale is outside 0..36');
  const amount = uint(amountMinor);
  if (fromDecimals <= toDecimals) {
    const value = requireUInt(
      amount * 10n ** BigInt(toDecimals - fromDecimals),
      'Scaled result',
    );
    return {
      valueMinor: text(value),
      remainder: { kind: 'EXACT', amountSourceMinor: '0', denominator: '1' },
    };
  }
  return mulDiv(
    amountMinor,
    '1',
    text(10n ** BigInt(fromDecimals - toDecimals)),
    rounding,
  );
}

export interface CreatePortfolioInput {
  experimentId: string;
  scenarioId: string;
  portfolioId: string;
  resultProvenance: ShadowPortfolioData['resultProvenance'];
  initialValueUsdcMinor: string;
  maxDestinationAttempts: string;
  balanceViews: ShadowPortfolioData['balanceViews'];
  initialCash: { viewId: string; amountUsdcMinor: string }[];
}

function familyForView(state: ShadowPortfolioData, viewId: string) {
  const view = state.balanceViews.find((item) => item.viewId === viewId);
  if (!view) fail(`Unknown balance view: ${viewId}`);
  return view;
}
function cashForFamily(state: ShadowPortfolioData, balanceFamilyId: string) {
  const cash = state.cash.find(
    (item) => item.balanceFamilyId === balanceFamilyId,
  );
  if (!cash) fail(`Missing cash balance family: ${balanceFamilyId}`);
  return cash;
}
function debitCash(
  state: ShadowPortfolioData,
  balanceFamilyId: string,
  amount: bigint,
) {
  const cash = cashForFamily(state, balanceFamilyId);
  const available = uint(cash.amountUsdcMinor);
  if (available < amount)
    throw new PoaError(
      'INSUFFICIENT_AVAILABLE_BALANCE',
      `Insufficient available cash in ${balanceFamilyId}`,
    );
  cash.amountUsdcMinor = text(available - amount);
}
function creditCash(
  state: ShadowPortfolioData,
  balanceFamilyId: string,
  amount: bigint,
) {
  const cash = cashForFamily(state, balanceFamilyId);
  cash.amountUsdcMinor = text(
    requireUInt(uint(cash.amountUsdcMinor) + amount, 'Cash balance'),
  );
}
function positionBook(shares: string, numerator: string, denominator: string) {
  return mulDiv(shares, numerator, denominator, 'FLOOR');
}
function sortState(state: ShadowPortfolioData) {
  state.balanceViews.sort(by((x) => x.viewId));
  state.cash.sort(by((x) => x.balanceFamilyId));
  state.reservations.sort(by((x) => x.reservationId));
  state.positions.sort(by((x) => x.positionId));
  state.receivables.sort(by((x) => x.transferId));
  state.payables.sort(by((x) => x.payableId));
  state.allowances.sort(by((x) => x.allowanceId));
  state.recognizedCosts.sort(by((x) => x.costId));
}

export function assertPortfolio(stateInput: ShadowPortfolioData) {
  const state = ShadowPortfolio.parse(stateInput);
  unique(state.balanceViews, (x) => x.viewId, 'balance view ID');
  unique(state.cash, (x) => x.balanceFamilyId, 'cash balance family');
  unique(state.reservations, (x) => x.reservationId, 'reservation ID');
  unique(state.positions, (x) => x.positionId, 'position ID');
  unique(state.receivables, (x) => x.transferId, 'transfer ID');
  unique(
    state.receivables,
    (x) => x.messageIdentity,
    'transfer message identity',
  );
  unique(state.payables, (x) => x.payableId, 'payable ID');
  unique(state.allowances, (x) => x.allowanceId, 'allowance ID');
  unique(state.recognizedCosts, (x) => x.costId, 'recognized cost ID');
  unique(state.appliedReceipts, (x) => x.operationId, 'applied operation ID');
  if (uint(state.version) !== BigInt(state.appliedReceipts.length))
    fail('Portfolio version must equal its applied receipt count');
  if ((state.version === '0') !== (state.lastAppliedAt === null))
    fail('Initial state alone may omit the last applied time');
  for (const [index, applied] of state.appliedReceipts.entries()) {
    if (uint(applied.versionApplied) !== BigInt(index + 1))
      fail('Applied receipt versions must be contiguous and ordered');
  }

  const families = new Map<string, (typeof state.balanceViews)[number]>();
  for (const view of state.balanceViews) {
    const family = families.get(view.balanceFamilyId);
    if (
      family &&
      (family.networkId !== view.networkId ||
        family.assetId !== view.assetId ||
        family.canonicalDecimals !== view.canonicalDecimals)
    )
      fail(
        `Balance family ${view.balanceFamilyId} aliases incompatible assets`,
      );
    families.set(view.balanceFamilyId, view);
  }
  for (const cash of state.cash) {
    const family = families.get(cash.balanceFamilyId);
    if (
      !family ||
      family.networkId !== cash.networkId ||
      family.assetId !== cash.assetId
    )
      fail(`Cash family ${cash.balanceFamilyId} has no matching view`);
  }
  if (families.size !== state.cash.length)
    fail('Every balance family must have exactly one canonical cash balance');
  for (const reservation of state.reservations) {
    const family = families.get(reservation.balanceFamilyId);
    if (
      !family ||
      family.networkId !== reservation.networkId ||
      family.assetId !== reservation.assetId
    )
      fail(
        `Reservation ${reservation.reservationId} has an invalid balance family`,
      );
    if (
      !state.appliedReceipts.some(
        (receipt) => receipt.operationId === reservation.operationId,
      )
    )
      fail(`Reservation ${reservation.reservationId} has no applied operation`);
  }
  for (const receivable of state.receivables) {
    const family = families.get(receivable.destinationBalanceFamilyId);
    if (!family || family.networkId !== receivable.destinationNetworkId)
      fail(`Receivable ${receivable.transferId} has an invalid destination`);
    if (receivable.sourceNetworkId === receivable.destinationNetworkId)
      fail(`Receivable ${receivable.transferId} has identical endpoints`);
    if (receivable.createdAt > receivable.updatedAt)
      fail(`Receivable ${receivable.transferId} moves backward in time`);
    if (
      uint(receivable.destinationAttempts) > uint(state.maxDestinationAttempts)
    )
      fail(`Receivable ${receivable.transferId} exceeds its attempt limit`);
    if (state.lastAppliedAt && receivable.updatedAt > state.lastAppliedAt)
      fail(`Receivable ${receivable.transferId} is newer than portfolio state`);
  }
  for (const position of state.positions) {
    if (
      !state.balanceViews.some(
        (view) =>
          view.networkId === position.networkId &&
          view.assetId === position.assetId,
      )
    )
      fail(
        `Position ${position.positionId} has an unknown network/asset identity`,
      );
    if (state.lastAppliedAt && position.lastObservedAt > state.lastAppliedAt)
      fail(`Position ${position.positionId} is newer than portfolio state`);
    const expected = positionBook(
      position.sharesMinor,
      position.indexNumerator,
      position.indexDenominator,
    );
    if (
      position.bookValueUsdcMinor !== expected.valueMinor ||
      position.roundingRemainderNumerator !==
        expected.remainder.amountSourceMinor
    )
      fail(`Position ${position.positionId} book value is not index-derived`);
  }
  for (const payable of state.payables) {
    const cost = state.recognizedCosts.find(
      (item) => item.costId === payable.costId,
    );
    if (
      !cost ||
      cost.funding !== 'PAYABLE' ||
      cost.amountUsdcMinor !== payable.amountUsdcMinor
    )
      fail(`Payable ${payable.payableId} is not backed by one recognized cost`);
  }
  for (const cost of state.recognizedCosts) {
    if (
      !state.appliedReceipts.some(
        (receipt) => receipt.operationId === cost.operationId,
      )
    )
      fail(`Cost ${cost.costId} does not reference an applied operation`);
  }
  for (const allowance of state.allowances) {
    if (
      !state.balanceViews.some(
        (view) =>
          view.networkId === allowance.networkId &&
          view.assetId === allowance.assetId,
      )
    )
      fail(`Allowance ${allowance.allowanceId} has an unknown network/asset`);
  }
  const grossAssets =
    total(state.cash.map((x) => x.amountUsdcMinor)) +
    total(state.reservations.map((x) => x.amountUsdcMinor)) +
    total(state.positions.map((x) => x.bookValueUsdcMinor)) +
    total(state.receivables.map((x) => x.amountUsdcMinor));
  const liabilities = total(state.payables.map((x) => x.amountUsdcMinor));
  if (liabilities > grossAssets) fail('Portfolio has negative net value');
  const netValue = grossAssets - liabilities;
  const expectedNet =
    uint(state.initialValueUsdcMinor) +
    BigInt(state.modeledPnlUsdcMinor) -
    total(state.recognizedCosts.map((x) => x.amountUsdcMinor));
  if (expectedNet < 0n || netValue !== expectedNet)
    fail(
      `Conservation failed: net=${netValue} expected=${expectedNet} ` +
        `(initial + modeled PnL - costs)`,
    );
  if ((state.closedAt === null) !== (state.deadlineStateHash === null))
    fail('Closure time and deadline state hash must appear together');
  if (
    state.closedAt &&
    state.lastAppliedAt &&
    state.closedAt > state.lastAppliedAt
  )
    fail('Closure cannot be newer than the latest applied receipt');
  return state;
}

export function createPortfolio(
  input: CreatePortfolioInput,
): ShadowPortfolioData {
  const cash = new Map<string, ShadowPortfolioData['cash'][number]>();
  for (const view of input.balanceViews) {
    const existing = cash.get(view.balanceFamilyId);
    if (!existing)
      cash.set(view.balanceFamilyId, {
        balanceFamilyId: view.balanceFamilyId,
        networkId: view.networkId,
        assetId: view.assetId,
        amountUsdcMinor: '0',
      });
  }
  const fundedFamilies = new Set<string>();
  for (const item of input.initialCash) {
    const view = input.balanceViews.find(
      (candidate) => candidate.viewId === item.viewId,
    );
    if (!view) fail(`Unknown initial cash view: ${item.viewId}`);
    if (fundedFamilies.has(view.balanceFamilyId))
      fail(`Initial cash duplicates balance family: ${view.balanceFamilyId}`);
    fundedFamilies.add(view.balanceFamilyId);
    const balance = cash.get(view.balanceFamilyId)!;
    balance.amountUsdcMinor = text(
      requireUInt(uint(item.amountUsdcMinor), 'Initial cash'),
    );
  }
  const state: ShadowPortfolioData = {
    schemaVersion: 'proof-of-alpha/shadow-portfolio/v1',
    accountingVersion: '1.0.0',
    experimentId: input.experimentId,
    scenarioId: input.scenarioId,
    portfolioId: input.portfolioId,
    resultProvenance: input.resultProvenance,
    unitOfAccount: 'USDC',
    unitDecimals: 6,
    initialValueUsdcMinor: input.initialValueUsdcMinor,
    maxDestinationAttempts: input.maxDestinationAttempts,
    version: '0',
    balanceViews: structuredClone(input.balanceViews),
    cash: [...cash.values()],
    reservations: [],
    positions: [],
    receivables: [],
    payables: [],
    allowances: [],
    recognizedCosts: [],
    modeledPnlUsdcMinor: '0',
    appliedReceipts: [],
    lastAppliedAt: null,
    closedAt: null,
    deadlineStateHash: null,
  };
  sortState(state);
  if (
    total(state.cash.map((x) => x.amountUsdcMinor)) !==
    uint(input.initialValueUsdcMinor)
  )
    fail('Initial cash must equal one scenario global capital exactly');
  return assertPortfolio(state);
}

function applyCosts(
  state: ShadowPortfolioData,
  receipt: AccountingReceiptData,
  costs: AccountingCostData[],
  expectedWithheld: bigint,
) {
  unique(costs, (cost) => cost.costId, 'cost ID in receipt');
  let withheld = 0n;
  for (const cost of costs) {
    if (!receipt.sourceHashes.includes(cost.sourceHash))
      fail(`Cost ${cost.costId} source is not archived by its receipt`);
    if (state.recognizedCosts.some((item) => item.costId === cost.costId))
      throw new PoaError(
        'OPERATION_CONFLICT',
        `Cost already recognized: ${cost.costId}`,
      );
    const amount = uint(cost.amountUsdcMinor);
    if (cost.funding === 'AVAILABLE_CASH') {
      if (!cost.cashBalanceFamilyId)
        fail(`Cash-funded cost ${cost.costId} needs a balance family`);
      if (
        cashForFamily(state, cost.cashBalanceFamilyId).networkId !==
        cost.networkId
      )
        fail(`Cash-funded cost ${cost.costId} names a different network`);
      debitCash(state, cost.cashBalanceFamilyId, amount);
    } else if (cost.funding === 'PAYABLE') {
      if (cost.cashBalanceFamilyId)
        fail(`Payable cost ${cost.costId} cannot name a cash family`);
      state.payables.push({
        payableId: cost.costId,
        costId: cost.costId,
        networkId: cost.networkId,
        amountUsdcMinor: cost.amountUsdcMinor,
      });
    } else {
      if (cost.cashBalanceFamilyId)
        fail(`Withheld cost ${cost.costId} cannot name a cash family`);
      withheld += amount;
    }
    state.recognizedCosts.push({ ...cost, operationId: receipt.operationId });
  }
  if (withheld !== expectedWithheld)
    fail(
      `Withheld costs ${withheld} do not match economic output gap ${expectedWithheld}`,
    );
}

const transferReceiptKinds = new Set<AccountingReceiptData['kind']>([
  'TRANSFER_READY',
  'TRANSFER_DELAYED',
  'TRANSFER_DESTINATION_RETRY',
  'TRANSFER_SETTLED',
]);

export function applyReceipt(
  stateInput: ShadowPortfolioData,
  receiptInput: AccountingReceiptData,
): ShadowPortfolioData {
  const original = assertPortfolio(stateInput);
  const receipt = AccountingReceipt.parse(receiptInput);
  const receiptHash = contentHash(receipt);
  const prior = original.appliedReceipts.find(
    (item) => item.operationId === receipt.operationId,
  );
  if (prior) {
    if (prior.receiptHash !== receiptHash)
      throw new PoaError(
        'OPERATION_CONFLICT',
        `Operation ${receipt.operationId} was already applied with different content`,
      );
    return original;
  }
  if (
    receipt.experimentId !== original.experimentId ||
    receipt.scenarioId !== original.scenarioId ||
    receipt.resultProvenance !== original.resultProvenance
  )
    fail(
      'Receipt experiment, scenario, or provenance binding does not match portfolio',
    );
  if (receipt.expectedPortfolioVersion !== original.version)
    throw new PoaError(
      'STALE_PORTFOLIO',
      `Expected version ${receipt.expectedPortfolioVersion}, current ${original.version}`,
    );
  if (original.lastAppliedAt && receipt.observedAt < original.lastAppliedAt)
    throw new PoaError(
      'INVALID_TRANSITION',
      'Receipt observation time cannot move backward',
    );
  if (original.closedAt && !transferReceiptKinds.has(receipt.kind))
    throw new PoaError(
      'CLOSED_PORTFOLIO',
      'Deadline state rejects new local economics',
    );

  const state = structuredClone(original);
  if (receipt.kind === 'NO_EFFECT') {
    // An authenticated pre-attempt rejection is durable but costs no gas.
  } else if (receipt.kind === 'RESERVE') {
    if (receipt.costs.length) fail('Reservation cannot incur an attempt cost');
    if (
      state.reservations.some(
        (item) => item.reservationId === receipt.reservationId,
      )
    )
      fail(`Reservation already exists: ${receipt.reservationId}`);
    const view = familyForView(state, receipt.cashViewId);
    debitCash(state, view.balanceFamilyId, uint(receipt.amountUsdcMinor));
    state.reservations.push({
      reservationId: receipt.reservationId,
      operationId: receipt.operationId,
      balanceFamilyId: view.balanceFamilyId,
      networkId: view.networkId,
      assetId: view.assetId,
      amountUsdcMinor: receipt.amountUsdcMinor,
    });
  } else if (receipt.kind === 'COST') {
    applyCosts(state, receipt, receipt.costs, 0n);
  } else if (receipt.kind === 'APPROVE') {
    const allowance = state.allowances.find(
      (item) => item.allowanceId === receipt.allowanceId,
    );
    if (allowance && uint(allowance.amountMinor) >= uint(receipt.amountMinor)) {
      if (receipt.costs.length)
        fail(
          'A sufficient existing allowance cannot incur another approval cost',
        );
    } else {
      applyCosts(state, receipt, receipt.costs, 0n);
    }
    if (
      allowance &&
      (allowance.networkId !== receipt.networkId ||
        allowance.assetId !== receipt.assetId ||
        allowance.spenderId !== receipt.spenderId)
    )
      fail('Allowance identity cannot change under an existing allowance ID');
    const value = {
      allowanceId: receipt.allowanceId,
      networkId: receipt.networkId,
      assetId: receipt.assetId,
      spenderId: receipt.spenderId,
      amountMinor: receipt.amountMinor,
    };
    if (allowance) Object.assign(allowance, value);
    else state.allowances.push(value);
  } else if (receipt.kind === 'DEPOSIT') {
    const view = familyForView(state, receipt.cashViewId);
    debitCash(state, view.balanceFamilyId, uint(receipt.inputUsdcMinor));
    let position = state.positions.find(
      (item) => item.positionId === receipt.positionId,
    );
    const beforeBook = position ? uint(position.bookValueUsdcMinor) : 0n;
    if (position) {
      if (
        position.networkId !== view.networkId ||
        position.instrumentId !== receipt.instrumentId ||
        position.assetId !== view.assetId ||
        position.indexNumerator !== receipt.indexNumerator ||
        position.indexDenominator !== receipt.indexDenominator
      )
        fail(
          'Existing position identity/index differs; accrue it before depositing',
        );
      position.sharesMinor = text(
        requireUInt(
          uint(position.sharesMinor) + uint(receipt.sharesCreditMinor),
          'Position shares',
        ),
      );
    } else {
      position = {
        positionId: receipt.positionId,
        networkId: view.networkId,
        instrumentId: receipt.instrumentId,
        assetId: view.assetId,
        sharesMinor: receipt.sharesCreditMinor,
        indexNumerator: receipt.indexNumerator,
        indexDenominator: receipt.indexDenominator,
        bookValueUsdcMinor: '0',
        roundingRemainderNumerator: '0',
        lastSourceHash: receipt.sourceHashes[0]!,
        lastObservedAt: receipt.observedAt,
      };
      state.positions.push(position);
    }
    const book = positionBook(
      position.sharesMinor,
      position.indexNumerator,
      position.indexDenominator,
    );
    position.bookValueUsdcMinor = book.valueMinor;
    position.roundingRemainderNumerator = book.remainder.amountSourceMinor;
    position.lastSourceHash = receipt.sourceHashes[0]!;
    position.lastObservedAt = receipt.observedAt;
    const credit = uint(position.bookValueUsdcMinor) - beforeBook;
    const input = uint(receipt.inputUsdcMinor);
    if (credit > input) fail('Deposit creates position value');
    applyCosts(state, receipt, receipt.costs, input - credit);
  } else if (receipt.kind === 'WITHDRAW') {
    const view = familyForView(state, receipt.cashViewId);
    const position = state.positions.find(
      (item) => item.positionId === receipt.positionId,
    );
    if (!position) transition(`Position not found: ${receipt.positionId}`);
    if (
      position.networkId !== view.networkId ||
      position.assetId !== view.assetId
    )
      fail('Withdrawal cash view does not match position asset/network');
    const debitShares = uint(receipt.sharesDebitMinor);
    const beforeShares = uint(position.sharesMinor);
    if (debitShares > beforeShares)
      transition('Withdrawal exceeds position shares');
    const beforeBook = uint(position.bookValueUsdcMinor);
    const remainingShares = beforeShares - debitShares;
    let afterBook = 0n;
    if (remainingShares === 0n) {
      state.positions = state.positions.filter(
        (item) => item.positionId !== receipt.positionId,
      );
    } else {
      position.sharesMinor = text(remainingShares);
      const book = positionBook(
        position.sharesMinor,
        position.indexNumerator,
        position.indexDenominator,
      );
      position.bookValueUsdcMinor = book.valueMinor;
      position.roundingRemainderNumerator = book.remainder.amountSourceMinor;
      position.lastSourceHash = receipt.sourceHashes[0]!;
      position.lastObservedAt = receipt.observedAt;
      afterBook = uint(book.valueMinor);
    }
    const bookDebit = beforeBook - afterBook;
    const cashCredit = uint(receipt.cashCreditUsdcMinor);
    if (cashCredit > bookDebit) fail('Withdrawal creates cash value');
    creditCash(state, view.balanceFamilyId, cashCredit);
    applyCosts(state, receipt, receipt.costs, bookDebit - cashCredit);
  } else if (receipt.kind === 'SWAP') {
    const source = familyForView(state, receipt.sourceCashViewId);
    const destination = familyForView(state, receipt.destinationCashViewId);
    if (source.balanceFamilyId === destination.balanceFamilyId)
      fail('Swap source and destination must be different balance families');
    if (source.networkId !== destination.networkId)
      fail('A swap cannot move value between networks; use a transfer');
    const debit = uint(receipt.sourceDebitUsdcMinor);
    const credit = uint(receipt.destinationCreditUsdcMinor);
    if (credit > debit) fail('Swap creates value without modeled PnL');
    debitCash(state, source.balanceFamilyId, debit);
    creditCash(state, destination.balanceFamilyId, credit);
    applyCosts(state, receipt, receipt.costs, debit - credit);
  } else if (receipt.kind === 'PAYABLE_SETTLED') {
    const view = familyForView(state, receipt.cashViewId);
    const payable = state.payables.find(
      (item) => item.payableId === receipt.payableId,
    );
    if (!payable)
      throw new PoaError(
        'PAYABLE_NOT_FOUND',
        `Payable not found: ${receipt.payableId}`,
      );
    if (payable.networkId !== view.networkId)
      fail('Payable must be settled from its network cash');
    debitCash(state, view.balanceFamilyId, uint(payable.amountUsdcMinor));
    state.payables = state.payables.filter(
      (item) => item.payableId !== receipt.payableId,
    );
  } else if (receipt.kind === 'TRANSFER_SOURCE_FAILED') {
    const reservation = state.reservations.find(
      (item) => item.reservationId === receipt.reservationId,
    );
    if (!reservation)
      transition(`Reservation not found: ${receipt.reservationId}`);
    const withheld = total(
      receipt.costs
        .filter((cost) => cost.funding === 'WITHHELD')
        .map((cost) => cost.amountUsdcMinor),
    );
    const amount = uint(reservation.amountUsdcMinor);
    if (withheld > amount) fail('Source failure costs exceed reservation');
    state.reservations = state.reservations.filter(
      (item) => item.reservationId !== receipt.reservationId,
    );
    creditCash(state, reservation.balanceFamilyId, amount - withheld);
    applyCosts(state, receipt, receipt.costs, withheld);
  } else if (receipt.kind === 'TRANSFER_BURNED') {
    const reservation = state.reservations.find(
      (item) => item.reservationId === receipt.reservationId,
    );
    if (!reservation)
      transition(`Reservation not found: ${receipt.reservationId}`);
    if (
      state.receivables.some(
        (item) =>
          item.transferId === receipt.transferId ||
          item.messageIdentity === receipt.messageIdentity,
      )
    )
      fail('Transfer ID or message identity already exists');
    const destination = familyForView(state, receipt.destinationCashViewId);
    if (destination.networkId !== receipt.destinationNetworkId)
      fail('Transfer destination view/network mismatch');
    if (reservation.networkId === destination.networkId)
      fail('Transfer source and destination networks must differ');
    const amount = uint(reservation.amountUsdcMinor);
    const receivable = uint(receipt.netReceivableUsdcMinor);
    if (receivable > amount) fail('Transfer burn creates receivable value');
    state.reservations = state.reservations.filter(
      (item) => item.reservationId !== receipt.reservationId,
    );
    state.receivables.push({
      transferId: receipt.transferId,
      messageIdentity: receipt.messageIdentity,
      sourceNetworkId: reservation.networkId,
      destinationNetworkId: receipt.destinationNetworkId,
      destinationBalanceFamilyId: destination.balanceFamilyId,
      amountUsdcMinor: receipt.netReceivableUsdcMinor,
      state: 'IN_TRANSIT',
      destinationAttempts: '0',
      createdAt: receipt.observedAt,
      updatedAt: receipt.observedAt,
    });
    applyCosts(state, receipt, receipt.costs, amount - receivable);
  } else if (
    receipt.kind === 'TRANSFER_READY' ||
    receipt.kind === 'TRANSFER_DELAYED' ||
    receipt.kind === 'TRANSFER_DESTINATION_RETRY' ||
    receipt.kind === 'TRANSFER_SETTLED'
  ) {
    const receivable = state.receivables.find(
      (item) => item.transferId === receipt.transferId,
    );
    if (!receivable) transition(`Transfer not found: ${receipt.transferId}`);
    if (receipt.observedAt < receivable.updatedAt)
      transition('Transfer observation time cannot move backward');
    if (receipt.kind === 'TRANSFER_READY') {
      if (
        !['IN_TRANSIT', 'DELAYED', 'DESTINATION_RETRY'].includes(
          receivable.state,
        )
      )
        transition(`Cannot mark ${receivable.state} ready`);
      if (
        receivable.state === 'DESTINATION_RETRY' &&
        uint(receivable.destinationAttempts) >=
          uint(state.maxDestinationAttempts)
      )
        transition(
          'Destination attempt limit reached; receivable stays blocked',
        );
      applyCosts(state, receipt, receipt.costs, 0n);
      receivable.state = 'READY_TO_RECEIVE';
      receivable.updatedAt = receipt.observedAt;
    } else if (receipt.kind === 'TRANSFER_DELAYED') {
      if (receivable.state !== 'IN_TRANSIT')
        transition(`Cannot delay ${receivable.state}`);
      applyCosts(state, receipt, receipt.costs, 0n);
      receivable.state = 'DELAYED';
      receivable.updatedAt = receipt.observedAt;
    } else if (receipt.kind === 'TRANSFER_DESTINATION_RETRY') {
      if (receivable.state !== 'READY_TO_RECEIVE')
        transition(`Cannot retry ${receivable.state}`);
      if (
        uint(receivable.destinationAttempts) >=
        uint(state.maxDestinationAttempts)
      )
        transition('Destination retry limit reached');
      applyCosts(state, receipt, receipt.costs, 0n);
      receivable.state = 'DESTINATION_RETRY';
      receivable.destinationAttempts = text(
        requireUInt(
          uint(receivable.destinationAttempts) + 1n,
          'Destination attempts',
        ),
      );
      receivable.updatedAt = receipt.observedAt;
    } else {
      if (receivable.state !== 'READY_TO_RECEIVE')
        transition(`Cannot settle ${receivable.state}`);
      const book = uint(receivable.amountUsdcMinor);
      const credit = uint(receipt.destinationCreditUsdcMinor);
      if (credit > book) fail('Destination settlement creates cash value');
      creditCash(state, receivable.destinationBalanceFamilyId, credit);
      state.receivables = state.receivables.filter(
        (item) => item.transferId !== receipt.transferId,
      );
      applyCosts(state, receipt, receipt.costs, book - credit);
    }
  } else if (receipt.kind === 'ACCRUE') {
    if (receipt.costs.length)
      fail('Index accrual cannot incur operation costs');
    const position = state.positions.find(
      (item) => item.positionId === receipt.positionId,
    );
    if (!position) transition(`Position not found: ${receipt.positionId}`);
    if (receipt.observedAt <= position.lastObservedAt)
      transition('Accrual observation must be later than prior position state');
    const before = uint(position.bookValueUsdcMinor);
    const book = positionBook(
      position.sharesMinor,
      receipt.nextIndexNumerator,
      receipt.nextIndexDenominator,
    );
    const after = uint(book.valueMinor);
    position.indexNumerator = receipt.nextIndexNumerator;
    position.indexDenominator = receipt.nextIndexDenominator;
    position.bookValueUsdcMinor = book.valueMinor;
    position.roundingRemainderNumerator = book.remainder.amountSourceMinor;
    position.lastSourceHash = receipt.sourceHashes[0]!;
    position.lastObservedAt = receipt.observedAt;
    state.modeledPnlUsdcMinor = text(
      BigInt(state.modeledPnlUsdcMinor) + (after - before),
    );
  } else if (receipt.kind === 'CLOSE') {
    if (receipt.closedAt !== receipt.observedAt)
      fail('Closure timestamp must equal its observed timestamp');
    state.closedAt = receipt.closedAt;
    state.deadlineStateHash = contentHash(original);
  }

  state.version = text(uint(original.version) + 1n);
  state.lastAppliedAt = receipt.observedAt;
  state.appliedReceipts.push({
    operationId: receipt.operationId,
    receiptHash,
    versionApplied: state.version,
  });
  sortState(state);
  return assertPortfolio(state);
}

export interface ReplayResult {
  state: ShadowPortfolioData;
  stateHashes: `0x${string}`[];
}

export function replay(
  initial: ShadowPortfolioData,
  receipts: AccountingReceiptData[],
  serializeAfterEveryReceipt = true,
): ReplayResult {
  let state = assertPortfolio(structuredClone(initial));
  const stateHashes = [contentHash(state)];
  for (const receipt of receipts) {
    state = applyReceipt(state, receipt);
    if (serializeAfterEveryReceipt)
      state = assertPortfolio(
        JSON.parse(JSON.stringify(state)) as ShadowPortfolioData,
      );
    stateHashes.push(contentHash(state));
  }
  return { state, stateHashes };
}

export function valuePortfolio(
  stateInput: ShadowPortfolioData,
  valuationInputs: PositionValuationInputData[],
): PortfolioValuationData {
  const state = assertPortfolio(stateInput);
  const inputs = valuationInputs.map((input) =>
    PositionValuationInput.parse(input),
  );
  unique(inputs, (input) => input.positionId, 'position valuation');
  if (
    inputs.length !== state.positions.length ||
    state.positions.some(
      (position) =>
        !inputs.some((input) => input.positionId === position.positionId),
    )
  )
    fail('Valuation must contain exactly one input for every open position');
  let dataQuality: PortfolioValuationData['dataQuality'] = inputs.some(
    (input) =>
      input.dataQuality === 'UNAVAILABLE' ||
      input.markValueUsdcMinor === null ||
      input.recoverableUsdcMinor === null ||
      input.exitCostUsdcMinor === null,
  )
    ? 'UNAVAILABLE'
    : inputs.some((input) => input.dataQuality === 'STALE')
      ? 'STALE'
      : 'FRESH';
  const available = total(state.cash.map((item) => item.amountUsdcMinor));
  const reserved = total(
    state.reservations.map((item) => item.amountUsdcMinor),
  );
  const inTransit = total(
    state.receivables.map((item) => item.amountUsdcMinor),
  );
  const payables = total(state.payables.map((item) => item.amountUsdcMinor));
  const reasonCodes: PortfolioValuationData['reasonCodes'] = [];
  if (dataQuality === 'UNAVAILABLE') reasonCodes.push('DATA_UNAVAILABLE');
  if (dataQuality === 'STALE') reasonCodes.push('STALE_DATA');
  if (inTransit > 0n) reasonCodes.push('IN_TRANSIT_UNAVAILABLE');
  let markValue: bigint | null = null;
  let liquidationValue: bigint | null = null;
  let blockedValue: bigint | null = null;
  if (dataQuality !== 'UNAVAILABLE') {
    let positionMarks = 0n;
    let positionLiquidation = 0n;
    let blocked = 0n;
    for (const input of inputs) {
      const mark = uint(input.markValueUsdcMinor!);
      const recoverable = uint(input.recoverableUsdcMinor!);
      const exitCost = uint(input.exitCostUsdcMinor!);
      if (exitCost > recoverable)
        fail('Exit cost exceeds recoverable position value');
      positionMarks += mark;
      positionLiquidation += recoverable - exitCost;
      if (recoverable < mark) blocked += mark - recoverable;
    }
    const grossMark = available + reserved + inTransit + positionMarks;
    const grossLiquidation = available + reserved + positionLiquidation;
    if (payables > grossMark || payables > grossLiquidation)
      fail('Valuation liabilities exceed recoverable assets');
    markValue = grossMark - payables;
    liquidationValue = grossLiquidation - payables;
    blockedValue = blocked;
    if (blocked > 0n) reasonCodes.push('BLOCKED_LIQUIDITY');
  }
  return PortfolioValuation.parse({
    schemaVersion: 'proof-of-alpha/portfolio-valuation/v1',
    accountingVersion: '1.0.0',
    portfolioHash: contentHash(state),
    portfolioVersion: state.version,
    markValueUsdcMinor: markValue === null ? null : text(markValue),
    liquidationValueUsdcMinor:
      liquidationValue === null ? null : text(liquidationValue),
    availableUsdcMinor: text(available),
    reservedUsdcMinor: text(reserved),
    inTransitUsdcMinor: text(inTransit),
    blockedValueUsdcMinor: blockedValue === null ? null : text(blockedValue),
    feesPayableUsdcMinor: text(payables),
    dataQuality,
    sourceHashes: inputs.map((input) => input.sourceHash).sort(),
    reasonCodes,
  });
}

export function globalBookValue(state: ShadowPortfolioData) {
  const valid = assertPortfolio(state);
  return text(
    total(valid.cash.map((x) => x.amountUsdcMinor)) +
      total(valid.reservations.map((x) => x.amountUsdcMinor)) +
      total(valid.positions.map((x) => x.bookValueUsdcMinor)) +
      total(valid.receivables.map((x) => x.amountUsdcMinor)) -
      total(valid.payables.map((x) => x.amountUsdcMinor)),
  );
}

import { mulDiv } from '@poa/accounting';
import { contentHash, PoaError } from '@poa/domain';
import {
  observationSourceHash,
  readArchivedJson,
  requireFresh,
  toSourceRef,
  type ObjectArchive,
} from '@poa/market-data';
import {
  AaveReservePayload,
  AdapterResult,
  Erc4626Payload,
  EthUsdcConversionPayload,
  GasPayload,
  UniswapV3QuotePayload,
  type AccountingCostData,
  type AccountingReceiptData,
  type AdapterResultData,
  type ArchivedObservationData,
  type AaveReservePayloadData,
  type Erc4626PayloadData,
  type EthUsdcConversionPayloadData,
  type GasPayloadData,
  type UniswapV3QuotePayloadData,
} from '@poa/schemas';

export const ADAPTER_VERSION = '1.0.0';

interface Captured<T> {
  observation: ArchivedObservationData;
  payload: T;
}

export interface ReceiptContext {
  experimentId: string;
  scenarioId: string;
  expectedPortfolioVersion: string;
  observedAt: string;
  evaluationTime: string;
  resultProvenance: AccountingReceiptData['resultProvenance'];
  cashViewId: string;
  cashBalanceFamilyId: string;
}

async function load<T>(
  archive: ObjectArchive,
  observation: ArchivedObservationData,
  schema: { parse(value: unknown): T },
  evaluationTime: string,
): Promise<Captured<T>> {
  requireFresh(observation, evaluationTime);
  const payload = schema.parse(
    await readArchivedJson(archive, observation.rawObject),
  );
  return { observation, payload };
}

function requireAligned(context: ReceiptContext, values: Captured<unknown>[]) {
  for (const value of values) {
    if (value.observation.adapterVersion !== ADAPTER_VERSION)
      throw new PoaError(
        'DEPENDENCY_UNVERIFIED',
        'Observation adapter version mismatch',
      );
    if (value.observation.resultProvenance !== context.resultProvenance)
      throw new PoaError(
        'ENVIRONMENT_MISMATCH',
        'Observation provenance mismatch',
      );
  }
}

function ceilMulDiv(a: string, b: string, d: string) {
  return mulDiv(a, b, d, 'CEIL').valueMinor;
}

function gasCost(
  id: string,
  gas: Captured<GasPayloadData>,
  conversion: Captured<EthUsdcConversionPayloadData>,
  category: AccountingCostData['category'],
  networkId = 'ethereum-mainnet',
): AccountingCostData {
  const wei =
    BigInt(gas.payload.gasUnits) * BigInt(gas.payload.effectiveGasPriceWei);
  const amount = ceilMulDiv(
    wei.toString(),
    conversion.payload.usdcMinorNumerator,
    conversion.payload.weiDenominator,
  );
  if (amount === '0')
    throw new PoaError(
      'ACCOUNTING_INVARIANT',
      'Attempted operation has zero modeled gas cost',
    );
  return {
    costId: id,
    category,
    funding: 'PAYABLE',
    amountUsdcMinor: amount,
    networkId,
    cashBalanceFamilyId: null,
    sourceHash: contentHash({
      gas: gas.observation.rawObject.objectHash,
      conversion: conversion.observation.rawObject.objectHash,
    }),
  };
}

function checkConversionFresh(
  conversion: Captured<EthUsdcConversionPayloadData>,
  evaluationTime: string,
) {
  const updated = Date.parse(conversion.payload.answerUpdatedAt);
  const evaluated = Date.parse(evaluationTime);
  const deadline =
    updated + Number(BigInt(conversion.payload.heartbeatSeconds) * 1000n);
  if (
    !Number.isFinite(updated) ||
    !Number.isFinite(evaluated) ||
    evaluated >= deadline
  )
    throw new PoaError(
      'DATA_STALE',
      'ETH/USDC conversion round exceeded its heartbeat',
    );
}

function sources(context: ReceiptContext, values: Captured<unknown>[]) {
  requireAligned(context, values);
  const refs = values.map((value) =>
    toSourceRef(value.observation, context.evaluationTime),
  );
  const derived = observationSourceHash(refs);
  const hashes = [...refs.map((ref) => ref.rawObjectHash), derived];
  return { refs, derived, hashes };
}

function result(
  adapterId: string,
  operation: string,
  context: ReceiptContext,
  refs: ReturnType<typeof toSourceRef>[],
  sourceHash: `0x${string}`,
  receipts: AccountingReceiptData[],
): AdapterResultData {
  return AdapterResult.parse({
    schemaVersion: 'proof-of-alpha/adapter-result/v1',
    adapterId,
    adapterVersion: ADAPTER_VERSION,
    operation,
    resultProvenance: context.resultProvenance,
    sourceRefs: refs,
    sourceHash,
    receipts,
  });
}

export async function erc20Approval(
  archive: ObjectArchive,
  context: ReceiptContext,
  input: {
    adapterId:
      | 'aave-v3-ethereum'
      | 'erc4626-ethereum'
      | 'demo-vault-ethereum-sepolia'
      | 'demo-vault-arc-testnet'
      | 'uniswap-v3-ethereum';
    operationId: string;
    allowanceId: string;
    assetId: 'usdc' | 'usdt';
    spenderId: string;
    amountMinor: string;
    currentAllowanceMinor: string;
    gas: ArchivedObservationData;
    conversion: ArchivedObservationData;
  },
) {
  const gas = await load(
    archive,
    input.gas,
    GasPayload,
    context.evaluationTime,
  );
  const conversion = await load(
    archive,
    input.conversion,
    EthUsdcConversionPayload,
    context.evaluationTime,
  );
  checkConversionFresh(conversion, context.evaluationTime);
  const source = sources(context, [gas, conversion]);
  if (
    gas.payload.operation !== 'APPROVE' ||
    gas.payload.amountInMinor !== input.amountMinor
  )
    throw new PoaError(
      'DATA_UNAVAILABLE',
      'Approval gas capture is not for the requested amount',
    );
  if (BigInt(input.currentAllowanceMinor) >= BigInt(input.amountMinor)) {
    const receipt: AccountingReceiptData = {
      schemaVersion: 'proof-of-alpha/accounting-receipt/v1',
      accountingVersion: '1.0.0',
      operationId: input.operationId,
      experimentId: context.experimentId,
      scenarioId: context.scenarioId,
      expectedPortfolioVersion: context.expectedPortfolioVersion,
      observedAt: context.observedAt,
      resultProvenance: context.resultProvenance,
      sourceHashes: source.hashes,
      kind: 'NO_EFFECT',
      status: 'SKIPPED',
      reasonCode: 'ALLOWANCE_SUFFICIENT',
      costs: [],
    };
    return result(
      input.adapterId,
      'erc20-approval',
      context,
      source.refs,
      source.derived,
      [receipt],
    );
  }
  const cost = gasCost(
    `${input.operationId}-gas`,
    gas,
    conversion,
    'APPROVAL_GAS',
  );
  const receipt: AccountingReceiptData = {
    schemaVersion: 'proof-of-alpha/accounting-receipt/v1',
    accountingVersion: '1.0.0',
    operationId: input.operationId,
    experimentId: context.experimentId,
    scenarioId: context.scenarioId,
    expectedPortfolioVersion: context.expectedPortfolioVersion,
    observedAt: context.observedAt,
    resultProvenance: context.resultProvenance,
    sourceHashes: [...source.hashes, cost.sourceHash],
    kind: 'APPROVE',
    allowanceId: input.allowanceId,
    networkId: 'ethereum-mainnet',
    assetId: input.assetId,
    spenderId: input.spenderId,
    amountMinor: input.amountMinor,
    costs: [cost],
  };
  return result(
    input.adapterId,
    'erc20-approval',
    context,
    source.refs,
    source.derived,
    [receipt],
  );
}

export async function aaveSupply(
  archive: ObjectArchive,
  context: ReceiptContext,
  input: {
    amountMinor: string;
    instrumentId: string;
    positionId: string;
    allowanceId: string;
    currentAllowanceMinor: string;
    reserve: ArchivedObservationData;
    approvalGas: ArchivedObservationData;
    supplyGas: ArchivedObservationData;
    conversion: ArchivedObservationData;
    operationPrefix?: string;
  },
) {
  const reserve = await load(
    archive,
    input.reserve,
    AaveReservePayload,
    context.evaluationTime,
  );
  const approvalGas = await load(
    archive,
    input.approvalGas,
    GasPayload,
    context.evaluationTime,
  );
  const supplyGas = await load(
    archive,
    input.supplyGas,
    GasPayload,
    context.evaluationTime,
  );
  const conversion = await load(
    archive,
    input.conversion,
    EthUsdcConversionPayload,
    context.evaluationTime,
  );
  checkConversionFresh(conversion, context.evaluationTime);
  const all = [reserve, approvalGas, supplyGas, conversion];
  const source = sources(context, all);
  const amount = BigInt(input.amountMinor);
  if (
    approvalGas.payload.amountInMinor !== input.amountMinor ||
    supplyGas.payload.amountInMinor !== input.amountMinor
  )
    throw new PoaError(
      'DATA_UNAVAILABLE',
      'Gas capture is not for the requested amount',
    );
  if (
    !reserve.payload.active ||
    reserve.payload.frozen ||
    reserve.payload.paused
  )
    throw new PoaError(
      'LIMIT_EXCEEDED',
      'Aave reserve is inactive, frozen, or paused',
    );
  if (
    BigInt(reserve.payload.supplyCapMinor) > 0n &&
    BigInt(reserve.payload.totalSuppliedMinor) + amount >
      BigInt(reserve.payload.supplyCapMinor)
  )
    throw new PoaError('LIMIT_EXCEEDED', 'Aave supply cap would be exceeded');
  const receipts: AccountingReceiptData[] = [];
  const approveOperationId = input.operationPrefix
    ? `${input.operationPrefix}-approve`
    : `${context.scenarioId}-aave-approve`;
  const depositOperationId = input.operationPrefix
    ? `${input.operationPrefix}-deposit`
    : `${context.scenarioId}-aave-supply`;
  let version = BigInt(context.expectedPortfolioVersion);
  if (BigInt(input.currentAllowanceMinor) < amount) {
    const cost = gasCost(
      input.operationPrefix
        ? `${input.operationPrefix}-approval-gas`
        : `${context.scenarioId}-aave-approval-gas`,
      approvalGas,
      conversion,
      'APPROVAL_GAS',
    );
    receipts.push({
      schemaVersion: 'proof-of-alpha/accounting-receipt/v1',
      accountingVersion: '1.0.0',
      operationId: approveOperationId,
      experimentId: context.experimentId,
      scenarioId: context.scenarioId,
      expectedPortfolioVersion: version.toString(),
      observedAt: context.observedAt,
      resultProvenance: context.resultProvenance,
      sourceHashes: [...source.hashes, cost.sourceHash],
      kind: 'APPROVE',
      allowanceId: input.allowanceId,
      networkId: 'ethereum-mainnet',
      assetId: reserve.payload.assetId,
      spenderId: 'aave-v3-pool',
      amountMinor: input.amountMinor,
      costs: [cost],
    });
    version++;
  }
  const supplyCost = gasCost(
    input.operationPrefix
      ? `${input.operationPrefix}-supply-gas`
      : `${context.scenarioId}-aave-supply-gas`,
    supplyGas,
    conversion,
    'EXECUTION_GAS',
  );
  receipts.push({
    schemaVersion: 'proof-of-alpha/accounting-receipt/v1',
    accountingVersion: '1.0.0',
    operationId: depositOperationId,
    experimentId: context.experimentId,
    scenarioId: context.scenarioId,
    expectedPortfolioVersion: version.toString(),
    observedAt: context.observedAt,
    resultProvenance: context.resultProvenance,
    sourceHashes: [...source.hashes, supplyCost.sourceHash],
    kind: 'DEPOSIT',
    cashViewId: context.cashViewId,
    positionId: input.positionId,
    instrumentId: input.instrumentId,
    sharesCreditMinor: input.amountMinor,
    indexNumerator: '1',
    indexDenominator: '1',
    inputUsdcMinor: input.amountMinor,
    costs: [supplyCost],
  });
  return result(
    'aave-v3-ethereum',
    'aave-supply',
    context,
    source.refs,
    source.derived,
    receipts,
  );
}

export async function aaveAccrue(
  archive: ObjectArchive,
  context: ReceiptContext,
  input: {
    positionId: string;
    openingLiquidityIndexRay: string;
    reserve: ArchivedObservationData;
  },
) {
  const reserve = await load(
    archive,
    input.reserve,
    AaveReservePayload,
    context.evaluationTime,
  );
  const source = sources(context, [reserve]);
  if (
    BigInt(reserve.payload.liquidityIndexRay) <
    BigInt(input.openingLiquidityIndexRay)
  )
    throw new PoaError(
      'ACCOUNTING_INVARIANT',
      'Aave liquidity index moved backward',
    );
  const receipt: AccountingReceiptData = {
    schemaVersion: 'proof-of-alpha/accounting-receipt/v1',
    accountingVersion: '1.0.0',
    operationId: `${context.scenarioId}-aave-accrue`,
    experimentId: context.experimentId,
    scenarioId: context.scenarioId,
    expectedPortfolioVersion: context.expectedPortfolioVersion,
    observedAt: context.observedAt,
    resultProvenance: context.resultProvenance,
    sourceHashes: source.hashes,
    kind: 'ACCRUE',
    positionId: input.positionId,
    nextIndexNumerator: reserve.payload.liquidityIndexRay,
    nextIndexDenominator: input.openingLiquidityIndexRay,
    costs: [],
  };
  return result(
    'aave-v3-ethereum',
    'aave-accrue',
    context,
    source.refs,
    source.derived,
    [receipt],
  );
}

export async function aaveWithdraw(
  archive: ObjectArchive,
  context: ReceiptContext,
  input: {
    positionId: string;
    sharesMinor: string;
    bookValueMinor: string;
    reserve: ArchivedObservationData;
    gas: ArchivedObservationData;
    conversion: ArchivedObservationData;
  },
) {
  const reserve = await load(
    archive,
    input.reserve,
    AaveReservePayload,
    context.evaluationTime,
  );
  const gas = await load(
    archive,
    input.gas,
    GasPayload,
    context.evaluationTime,
  );
  const conversion = await load(
    archive,
    input.conversion,
    EthUsdcConversionPayload,
    context.evaluationTime,
  );
  checkConversionFresh(conversion, context.evaluationTime);
  const source = sources(context, [reserve, gas, conversion]);
  if (gas.payload.amountInMinor !== input.bookValueMinor)
    throw new PoaError(
      'DATA_UNAVAILABLE',
      'Withdrawal gas capture is not for the requested amount',
    );
  if (
    BigInt(reserve.payload.availableLiquidityMinor) <
    BigInt(input.bookValueMinor)
  )
    throw new PoaError(
      'LIQUIDITY_UNAVAILABLE',
      'Aave reserve cannot satisfy the withdrawal',
    );
  const cost = gasCost(
    `${context.scenarioId}-aave-withdraw-gas`,
    gas,
    conversion,
    'EXECUTION_GAS',
  );
  const receipt: AccountingReceiptData = {
    schemaVersion: 'proof-of-alpha/accounting-receipt/v1',
    accountingVersion: '1.0.0',
    operationId: `${context.scenarioId}-aave-withdraw`,
    experimentId: context.experimentId,
    scenarioId: context.scenarioId,
    expectedPortfolioVersion: context.expectedPortfolioVersion,
    observedAt: context.observedAt,
    resultProvenance: context.resultProvenance,
    sourceHashes: [...source.hashes, cost.sourceHash],
    kind: 'WITHDRAW',
    costs: [cost],
    cashViewId: context.cashViewId,
    positionId: input.positionId,
    sharesDebitMinor: input.sharesMinor,
    cashCreditUsdcMinor: input.bookValueMinor,
  };
  return result(
    'aave-v3-ethereum',
    'aave-withdraw',
    context,
    source.refs,
    source.derived,
    [receipt],
  );
}

export function erc4626ConvertToShares(
  assets: string,
  totalAssets: string,
  totalShares: string,
  rounding: 'FLOOR' | 'CEIL',
) {
  if (totalAssets === '0' || totalShares === '0') return assets;
  return mulDiv(assets, totalShares, totalAssets, rounding).valueMinor;
}

export async function vaultDeposit(
  archive: ObjectArchive,
  context: ReceiptContext,
  input: {
    amountMinor: string;
    instrumentId: string;
    positionId: string;
    vault: ArchivedObservationData;
    gas: ArchivedObservationData;
    conversion: ArchivedObservationData;
    adapterId?:
      | 'erc4626-ethereum'
      | 'demo-vault-ethereum-sepolia'
      | 'demo-vault-arc-testnet';
    networkId?: string;
  },
) {
  const vault = await load(
    archive,
    input.vault,
    Erc4626Payload,
    context.evaluationTime,
  );
  const gas = await load(
    archive,
    input.gas,
    GasPayload,
    context.evaluationTime,
  );
  const conversion = await load(
    archive,
    input.conversion,
    EthUsdcConversionPayload,
    context.evaluationTime,
  );
  checkConversionFresh(conversion, context.evaluationTime);
  const source = sources(context, [vault, gas, conversion]);
  if (
    vault.payload.testAmountAssetsMinor !== input.amountMinor ||
    gas.payload.amountInMinor !== input.amountMinor
  )
    throw new PoaError(
      'DATA_UNAVAILABLE',
      'Vault capture is not for the requested amount',
    );
  if (
    BigInt(input.amountMinor) > BigInt(vault.payload.maxDepositAssetsMinor) ||
    BigInt(vault.payload.previewDepositShares) >
      BigInt(vault.payload.maxMintShares)
  )
    throw new PoaError('LIMIT_EXCEEDED', 'Vault entry limit would be exceeded');
  if (vault.payload.previewDepositShares === '0')
    throw new PoaError('LIMIT_EXCEEDED', 'Vault deposit rounds to zero shares');
  const gasCharge = gasCost(
    `${context.scenarioId}-vault-deposit-gas`,
    gas,
    conversion,
    'EXECUTION_GAS',
    input.networkId,
  );
  const fee = mulDiv(
    input.amountMinor,
    String(vault.payload.depositFeeBps),
    '10000',
    'CEIL',
  ).valueMinor;
  const costs: AccountingCostData[] = [gasCharge];
  if (fee !== '0')
    costs.push({
      costId: `${context.scenarioId}-vault-entry-fee`,
      category: 'PROTOCOL_FEE',
      funding: 'WITHHELD',
      amountUsdcMinor: fee,
      networkId: input.networkId ?? 'ethereum-mainnet',
      cashBalanceFamilyId: null,
      sourceHash: vault.observation.rawObject.objectHash,
    });
  const credited = (BigInt(input.amountMinor) - BigInt(fee)).toString();
  const receipt: AccountingReceiptData = {
    schemaVersion: 'proof-of-alpha/accounting-receipt/v1',
    accountingVersion: '1.0.0',
    operationId: `${context.scenarioId}-vault-deposit`,
    experimentId: context.experimentId,
    scenarioId: context.scenarioId,
    expectedPortfolioVersion: context.expectedPortfolioVersion,
    observedAt: context.observedAt,
    resultProvenance: context.resultProvenance,
    sourceHashes: [...source.hashes, ...costs.map((cost) => cost.sourceHash)],
    kind: 'DEPOSIT',
    costs,
    cashViewId: context.cashViewId,
    positionId: input.positionId,
    instrumentId: input.instrumentId,
    sharesCreditMinor: vault.payload.previewDepositShares,
    indexNumerator: credited,
    indexDenominator: vault.payload.previewDepositShares,
    inputUsdcMinor: input.amountMinor,
  };
  return result(
    input.adapterId ?? 'erc4626-ethereum',
    'vault-deposit',
    context,
    source.refs,
    source.derived,
    [receipt],
  );
}

export async function vaultRedeem(
  archive: ObjectArchive,
  context: ReceiptContext,
  input: {
    sharesMinor: string;
    bookValueMinor: string;
    positionId: string;
    vault: ArchivedObservationData;
    gas: ArchivedObservationData;
    conversion: ArchivedObservationData;
    adapterId?:
      | 'erc4626-ethereum'
      | 'demo-vault-ethereum-sepolia'
      | 'demo-vault-arc-testnet';
    networkId?: string;
  },
) {
  const vault = await load(
    archive,
    input.vault,
    Erc4626Payload,
    context.evaluationTime,
  );
  const gas = await load(
    archive,
    input.gas,
    GasPayload,
    context.evaluationTime,
  );
  const conversion = await load(
    archive,
    input.conversion,
    EthUsdcConversionPayload,
    context.evaluationTime,
  );
  checkConversionFresh(conversion, context.evaluationTime);
  const source = sources(context, [vault, gas, conversion]);
  if (gas.payload.amountInMinor !== input.bookValueMinor)
    throw new PoaError(
      'DATA_UNAVAILABLE',
      'Vault redeem gas capture is not for the requested amount',
    );
  if (
    BigInt(input.sharesMinor) > BigInt(vault.payload.maxRedeemShares) ||
    BigInt(vault.payload.previewRedeemAssetsMinor) >
      BigInt(vault.payload.maxWithdrawAssetsMinor)
  )
    throw new PoaError('LIMIT_EXCEEDED', 'Vault exit limit would be exceeded');
  if (
    BigInt(vault.payload.previewRedeemAssetsMinor) >
    BigInt(vault.payload.availableExitAssetsMinor)
  )
    throw new PoaError(
      'LIQUIDITY_UNAVAILABLE',
      'Vault cannot satisfy the redeem',
    );
  const gross = BigInt(vault.payload.previewRedeemAssetsMinor);
  const fee = BigInt(
    mulDiv(
      gross.toString(),
      String(vault.payload.redeemFeeBps),
      '10000',
      'CEIL',
    ).valueMinor,
  );
  if (gross < fee)
    throw new PoaError('ACCOUNTING_INVARIANT', 'Vault exit fee exceeds output');
  const cashCredit = gross - fee;
  if (cashCredit > BigInt(input.bookValueMinor))
    throw new PoaError(
      'ACCOUNTING_INVARIANT',
      'Vault redeem creates unaccrued value',
    );
  const gasCharge = gasCost(
    `${context.scenarioId}-vault-redeem-gas`,
    gas,
    conversion,
    'EXECUTION_GAS',
    input.networkId,
  );
  const economicGap = BigInt(input.bookValueMinor) - cashCredit;
  const costs: AccountingCostData[] = [gasCharge];
  if (economicGap > 0n)
    costs.push({
      costId: `${context.scenarioId}-vault-exit-gap`,
      category: 'PROTOCOL_FEE',
      funding: 'WITHHELD',
      amountUsdcMinor: economicGap.toString(),
      networkId: input.networkId ?? 'ethereum-mainnet',
      cashBalanceFamilyId: null,
      sourceHash: vault.observation.rawObject.objectHash,
    });
  const receipt: AccountingReceiptData = {
    schemaVersion: 'proof-of-alpha/accounting-receipt/v1',
    accountingVersion: '1.0.0',
    operationId: `${context.scenarioId}-vault-redeem`,
    experimentId: context.experimentId,
    scenarioId: context.scenarioId,
    expectedPortfolioVersion: context.expectedPortfolioVersion,
    observedAt: context.observedAt,
    resultProvenance: context.resultProvenance,
    sourceHashes: [...source.hashes, ...costs.map((cost) => cost.sourceHash)],
    kind: 'WITHDRAW',
    costs,
    cashViewId: context.cashViewId,
    positionId: input.positionId,
    sharesDebitMinor: input.sharesMinor,
    cashCreditUsdcMinor: cashCredit.toString(),
  };
  return result(
    input.adapterId ?? 'erc4626-ethereum',
    'vault-redeem',
    context,
    source.refs,
    source.derived,
    [receipt],
  );
}

export async function selectUniswapQuote(
  archive: ObjectArchive,
  context: ReceiptContext,
  observations: ArchivedObservationData[],
  gasObservation: ArchivedObservationData,
  conversionObservation: ArchivedObservationData,
  input: {
    amountInMinor: string;
    assetIn: 'usdc' | 'usdt';
    assetOut: 'usdc' | 'usdt';
    minimumOutMinor: string;
  },
) {
  const quotes = await Promise.all(
    observations.map((item) =>
      load(archive, item, UniswapV3QuotePayload, context.evaluationTime),
    ),
  );
  const gas = await load(
    archive,
    gasObservation,
    GasPayload,
    context.evaluationTime,
  );
  const conversion = await load(
    archive,
    conversionObservation,
    EthUsdcConversionPayload,
    context.evaluationTime,
  );
  checkConversionFresh(conversion, context.evaluationTime);
  if (gas.payload.amountInMinor !== input.amountInMinor)
    throw new PoaError(
      'DATA_UNAVAILABLE',
      'Swap gas capture is not for the requested amount',
    );
  const candidates = quotes.filter(
    (quote) =>
      quote.payload.amountInMinor === input.amountInMinor &&
      quote.payload.assetIn === input.assetIn &&
      quote.payload.assetOut === input.assetOut,
  );
  if (!candidates.length)
    throw new PoaError('QUOTE_UNAVAILABLE', 'No exact-amount direct quote');
  const gasCharge = gasCost(
    `${context.scenarioId}-swap-gas`,
    gas,
    conversion,
    'EXECUTION_GAS',
  );
  candidates.sort((a, b) => {
    const av =
      BigInt(a.payload.amountOutMinor) - BigInt(gasCharge.amountUsdcMinor);
    const bv =
      BigInt(b.payload.amountOutMinor) - BigInt(gasCharge.amountUsdcMinor);
    return av === bv
      ? a.payload.poolId.localeCompare(b.payload.poolId)
      : av > bv
        ? -1
        : 1;
  });
  const selected = candidates[0]!;
  if (BigInt(selected.payload.amountOutMinor) < BigInt(input.minimumOutMinor))
    throw new PoaError(
      'SLIPPAGE_EXCEEDED',
      'Exact-input quote is below minimum output',
    );
  return { selected, gas, conversion, gasCharge };
}

export async function uniswapSwap(
  archive: ObjectArchive,
  context: ReceiptContext,
  input: {
    amountInMinor: string;
    assetIn: 'usdc' | 'usdt';
    assetOut: 'usdc' | 'usdt';
    minimumOutMinor: string;
    sourceCashViewId: string;
    destinationCashViewId: string;
    quotes: ArchivedObservationData[];
    gas: ArchivedObservationData;
    conversion: ArchivedObservationData;
  },
) {
  const chosen = await selectUniswapQuote(
    archive,
    context,
    input.quotes,
    input.gas,
    input.conversion,
    input,
  );
  const source = sources(context, [
    chosen.selected,
    chosen.gas,
    chosen.conversion,
  ]);
  const impact = (
    BigInt(input.amountInMinor) - BigInt(chosen.selected.payload.amountOutMinor)
  ).toString();
  if (BigInt(impact) < 0n)
    throw new PoaError(
      'ACCOUNTING_INVARIANT',
      'Unit-of-account swap output exceeds input',
    );
  const costs: AccountingCostData[] = [chosen.gasCharge];
  if (impact !== '0')
    costs.push({
      costId: `${context.scenarioId}-swap-fee-impact`,
      category: 'SWAP_FEE_IMPACT',
      funding: 'WITHHELD',
      amountUsdcMinor: impact,
      networkId: 'ethereum-mainnet',
      cashBalanceFamilyId: null,
      sourceHash: chosen.selected.observation.rawObject.objectHash,
    });
  const receipt: AccountingReceiptData = {
    schemaVersion: 'proof-of-alpha/accounting-receipt/v1',
    accountingVersion: '1.0.0',
    operationId: `${context.scenarioId}-uniswap-swap`,
    experimentId: context.experimentId,
    scenarioId: context.scenarioId,
    expectedPortfolioVersion: context.expectedPortfolioVersion,
    observedAt: context.observedAt,
    resultProvenance: context.resultProvenance,
    sourceHashes: [...source.hashes, ...costs.map((cost) => cost.sourceHash)],
    kind: 'SWAP',
    costs,
    sourceCashViewId: input.sourceCashViewId,
    destinationCashViewId: input.destinationCashViewId,
    sourceDebitUsdcMinor: input.amountInMinor,
    destinationCreditUsdcMinor: chosen.selected.payload.amountOutMinor,
  };
  return result(
    'uniswap-v3-ethereum',
    'uniswap-swap',
    context,
    source.refs,
    source.derived,
    [receipt],
  );
}

export type {
  AaveReservePayloadData,
  Erc4626PayloadData,
  EthUsdcConversionPayloadData,
  GasPayloadData,
  UniswapV3QuotePayloadData,
};

import {
  encodeAbiParameters,
  hexToBytes,
  keccak256,
  toBytes,
  type Hex,
} from 'viem';
import {
  canonicalJson,
  contentHash,
  PoaError,
  rawBytesHash,
} from '@poa/domain';
import {
  AuditEvent,
  CommitmentBatch,
  CommitmentLeaf,
  CommitmentLeafSet,
  MerkleProof,
  RegistryPublicationReceipt,
  ReproducibleExport,
  type AuditEventData,
  type CommitmentBatchData,
  type CommitmentLeafData,
  type MerkleProofData,
  type RegistryPublicationReceiptData,
  type ReproducibleExportData,
} from '@poa/schemas';

export const LEAF_DOMAIN = 'PROOF_OF_ALPHA_AUDIT_LEAF_V1' as const;
export const NODE_DOMAIN = 'PROOF_OF_ALPHA_MERKLE_NODE_V1' as const;
export const BATCH_DOMAIN = 'PROOF_OF_ALPHA_COMMITMENT_BATCH_V1' as const;
export const ZERO_HASH = `0x${'0'.repeat(64)}` as Hex;
const textEncoder = new TextEncoder();

function concatBytes(...parts: Uint8Array[]) {
  const result = new Uint8Array(
    parts.reduce((sum, part) => sum + part.length, 0),
  );
  let offset = 0;
  for (const part of parts) {
    result.set(part, offset);
    offset += part.length;
  }
  return result;
}

export function auditEventHash(eventInput: AuditEventData) {
  return contentHash(AuditEvent.parse(eventInput));
}

export function assertAuditContinuity(eventsInput: AuditEventData[]) {
  const events = eventsInput.map((event) => AuditEvent.parse(event));
  let previous: Hex | null = null;
  for (const [index, event] of events.entries()) {
    if (BigInt(event.sequence) !== BigInt(index + 1))
      throw new PoaError(
        'BATCH_CONTINUITY',
        'Audit sequence has a gap or overlap',
      );
    if (event.previousEventHash !== previous)
      throw new PoaError('BATCH_CONTINUITY', 'Audit event predecessor differs');
    previous = auditEventHash(event);
  }
  return events;
}

export function createAuditEvent(input: {
  experimentId: string;
  sequence: string;
  objectType: AuditEventData['objectType'];
  occurredAt: string;
  resultProvenance: AuditEventData['resultProvenance'];
  objectSchemaVersion: string;
  contentHash: Hex;
  previousEvent?: AuditEventData | null;
  supersedesContentHash?: Hex | null;
}) {
  const previous = input.previousEvent ?? null;
  if (
    BigInt(input.sequence) !== BigInt(previous?.sequence ?? '0') + 1n ||
    (previous && previous.experimentId !== input.experimentId)
  )
    throw new PoaError('BATCH_CONTINUITY', 'Audit event is not the next event');
  return AuditEvent.parse({
    schemaVersion: 'proof-of-alpha/audit-event/v1',
    experimentId: input.experimentId,
    sequence: input.sequence,
    objectType: input.objectType,
    occurredAt: input.occurredAt,
    resultProvenance: input.resultProvenance,
    objectSchemaVersion: input.objectSchemaVersion,
    contentHash: input.contentHash,
    previousEventHash: previous ? auditEventHash(previous) : null,
    supersedesContentHash: input.supersedesContentHash ?? null,
  });
}

export function leafHash(eventInput: AuditEventData): Hex {
  const event = AuditEvent.parse(eventInput);
  const body = {
    domain: LEAF_DOMAIN,
    experimentId: event.experimentId,
    sequence: event.sequence,
    objectType: event.objectType,
    objectSchemaVersion: event.objectSchemaVersion,
    contentHash: event.contentHash,
    auditEventHash: auditEventHash(event),
  };
  return rawBytesHash(
    concatBytes(
      textEncoder.encode(`${LEAF_DOMAIN}\0`),
      textEncoder.encode(canonicalJson(body)),
    ),
  );
}

export function createLeaf(eventInput: AuditEventData): CommitmentLeafData {
  const event = AuditEvent.parse(eventInput);
  return CommitmentLeaf.parse({
    schemaVersion: 'proof-of-alpha/commitment-leaf/v1',
    domain: LEAF_DOMAIN,
    experimentId: event.experimentId,
    sequence: event.sequence,
    objectType: event.objectType,
    objectSchemaVersion: event.objectSchemaVersion,
    contentHash: event.contentHash,
    auditEventHash: auditEventHash(event),
    leafHash: leafHash(event),
  });
}

function nodeHash(left: Hex, right: Hex): Hex {
  return rawBytesHash(
    concatBytes(
      textEncoder.encode(`${NODE_DOMAIN}\0`),
      hexToBytes(left),
      hexToBytes(right),
    ),
  );
}

function nextLevel(level: Hex[]) {
  const next: Hex[] = [];
  for (let index = 0; index < level.length; index += 2)
    next.push(nodeHash(level[index]!, level[index + 1] ?? level[index]!));
  return next;
}

export function merkleRoot(hashes: Hex[]): Hex {
  if (!hashes.length)
    throw new PoaError('COMMITMENT_INVALID', 'Merkle tree requires a leaf');
  let level = [...hashes];
  while (level.length > 1) level = nextLevel(level);
  return level[0]!;
}

export function createProof(
  batchId: string,
  hashes: Hex[],
  leafIndex: number,
): MerkleProofData {
  if (
    !Number.isInteger(leafIndex) ||
    leafIndex < 0 ||
    leafIndex >= hashes.length
  )
    throw new PoaError(
      'COMMITMENT_INVALID',
      'Merkle leaf index is out of range',
    );
  const siblings: MerkleProofData['siblings'] = [];
  let index = leafIndex;
  let level = [...hashes];
  while (level.length > 1) {
    const siblingIndex = index % 2 === 0 ? index + 1 : index - 1;
    siblings.push({
      side: index % 2 === 0 ? 'RIGHT' : 'LEFT',
      hash: level[siblingIndex] ?? level[index]!,
    });
    index = Math.floor(index / 2);
    level = nextLevel(level);
  }
  return MerkleProof.parse({
    schemaVersion: 'proof-of-alpha/merkle-proof/v1',
    batchId,
    leafHash: hashes[leafIndex]!,
    leafIndex,
    leafCount: hashes.length,
    siblings,
    root: level[0],
  });
}

export function verifyProof(proofInput: MerkleProofData) {
  const proof = MerkleProof.parse(proofInput);
  let value = proof.leafHash as Hex;
  for (const sibling of proof.siblings)
    value =
      sibling.side === 'LEFT'
        ? nodeHash(sibling.hash as Hex, value)
        : nodeHash(value, sibling.hash as Hex);
  if (value !== proof.root)
    throw new PoaError('COMMITMENT_INVALID', 'Merkle inclusion proof differs');
  return true;
}

export function experimentIdHash(experimentId: string): Hex {
  return keccak256(toBytes(experimentId));
}

export function commitmentBatchHash(batchInput: CommitmentBatchData): Hex {
  const batch = CommitmentBatch.parse(batchInput);
  return keccak256(
    encodeAbiParameters(
      [
        { type: 'bytes32' },
        { type: 'bytes32' },
        { type: 'uint64' },
        { type: 'uint64' },
        { type: 'bytes32' },
        { type: 'bytes32' },
        { type: 'bytes32' },
      ],
      [
        keccak256(toBytes(BATCH_DOMAIN)),
        experimentIdHash(batch.experimentId),
        BigInt(batch.firstSequence),
        BigInt(batch.lastSequence),
        batch.root as Hex,
        (batch.previousBatchHash ?? ZERO_HASH) as Hex,
        batch.leavesObjectHash as Hex,
      ],
    ),
  );
}

export function buildBatch(input: {
  experimentId: string;
  batchId: string;
  events: AuditEventData[];
  previousBatchHash?: Hex | null;
  registryNetworkId?: string;
  status?: CommitmentBatchData['status'];
  transactionHash?: Hex | null;
  block?: CommitmentBatchData['block'];
}) {
  if (!input.events.length)
    throw new PoaError('COMMITMENT_INVALID', 'Batch requires audit events');
  const events = input.events.map((event) => AuditEvent.parse(event));
  for (const [index, event] of events.entries()) {
    if (event.experimentId !== input.experimentId)
      throw new PoaError('PROVENANCE_SPLICE', 'Batch combines experiments');
    if (
      index &&
      BigInt(event.sequence) !== BigInt(events[index - 1]!.sequence) + 1n
    )
      throw new PoaError(
        'BATCH_CONTINUITY',
        'Batch sequence has a gap or overlap',
      );
  }
  const leaves = events.map(createLeaf);
  const leafSet = CommitmentLeafSet.parse({
    schemaVersion: 'proof-of-alpha/commitment-leaf-set/v1',
    batchId: input.batchId,
    firstSequence: events[0]!.sequence,
    lastSequence: events.at(-1)!.sequence,
    leaves,
  });
  const root = merkleRoot(leaves.map((leaf) => leaf.leafHash as Hex));
  const batch = CommitmentBatch.parse({
    schemaVersion: 'proof-of-alpha/commitment-batch/v1',
    experimentId: input.experimentId,
    batchId: input.batchId,
    firstSequence: events[0]!.sequence,
    lastSequence: events.at(-1)!.sequence,
    root,
    previousBatchHash: input.previousBatchHash ?? null,
    leavesObjectHash: contentHash(leafSet),
    mode: 'PERIODIC_AFTER_RECEIPT',
    registryNetworkId: input.registryNetworkId ?? 'arc-testnet',
    status: input.status ?? 'PENDING',
    transactionHash: input.transactionHash ?? null,
    block: input.block ?? null,
  });
  return {
    batch,
    batchHash: commitmentBatchHash(batch),
    leafSet,
    proofs: leaves.map((_, index) =>
      createProof(
        input.batchId,
        leaves.map((leaf) => leaf.leafHash as Hex),
        index,
      ),
    ),
  };
}

export function assertBatchContinuity(batchesInput: CommitmentBatchData[]) {
  const batches = batchesInput.map((batch) => CommitmentBatch.parse(batch));
  let last = 0n;
  let previous: Hex | null = null;
  let experimentId: string | null = null;
  for (const batch of batches) {
    if (experimentId && batch.experimentId !== experimentId)
      throw new PoaError(
        'PROVENANCE_SPLICE',
        'Batch chain combines experiments',
      );
    if (BigInt(batch.firstSequence) !== last + 1n)
      throw new PoaError(
        'BATCH_CONTINUITY',
        'Batch chain has a gap or overlap',
      );
    if (batch.previousBatchHash !== previous)
      throw new PoaError('BATCH_CONTINUITY', 'Batch predecessor differs');
    experimentId = batch.experimentId;
    last = BigInt(batch.lastSequence);
    previous = commitmentBatchHash(batch);
  }
  return true;
}

export function verifyPublication(
  batchInput: CommitmentBatchData,
  receiptInput: RegistryPublicationReceiptData,
  canonical?: { blockHash: Hex; registryCodeHash: Hex },
) {
  const batch = CommitmentBatch.parse(batchInput);
  const receipt = RegistryPublicationReceipt.parse(receiptInput);
  if (
    receipt.batchId !== batch.batchId ||
    receipt.batchHash !== commitmentBatchHash(batch) ||
    receipt.experimentIdHash !== experimentIdHash(batch.experimentId) ||
    receipt.registryNetworkId !== batch.registryNetworkId
  )
    throw new PoaError(
      'COMMITMENT_INVALID',
      'Registry receipt does not bind the batch',
    );
  if (
    receipt.status === 'REORGED' ||
    (canonical?.blockHash !== undefined &&
      canonical.blockHash !== receipt.block.hash) ||
    (canonical?.registryCodeHash !== undefined &&
      canonical.registryCodeHash !== receipt.registryCodeHash)
  )
    throw new PoaError(
      'PUBLICATION_REORGED',
      'Registry publication is not canonical',
    );
  return true;
}

const REQUIRED_EXPORT_TYPES = [
  'SCHEMA_CATALOG',
  'FROZEN_POLICY',
  'FROZEN_CONFIGURATION',
  'FROZEN_PROFILE',
  'ADAPTER_SET',
  'PARSER_SET',
  'SIGNED_INTENT',
  'RAW_INPUT_DESCRIPTOR',
  'RAW_INPUT',
  'ACCOUNTING_RECEIPT',
  'EXECUTION_RECEIPT',
  'TRANSFER_RECEIPT',
  'CHECKPOINT',
  'SCENARIO_EVALUATION',
  'ELIGIBILITY_EVALUATION',
] as const;

export const SUPPORTED_EXPORT_ENGINES = {
  accounting: '1.0.0',
  planner: '1.0.0',
  execution: '1.0.0',
  valuation: '1.0.0',
  evaluation: '1.0.0',
  commitments: '1.0.0',
  export: '1.0.0',
} as const;

export function verifyExport(input: ReproducibleExportData) {
  const bundle = ReproducibleExport.parse(input);
  for (const [engine, version] of Object.entries(SUPPORTED_EXPORT_ENGINES))
    if (
      bundle.engineVersions[engine as keyof typeof bundle.engineVersions] !==
      version
    )
      throw new PoaError(
        'VERSION_DRIFT',
        `Unsupported ${engine} engine version`,
      );
  const types = new Set(bundle.objects.map((object) => object.objectType));
  for (const type of REQUIRED_EXPORT_TYPES)
    if (!types.has(type))
      throw new PoaError('EXPORT_INCOMPLETE', `Export omits ${type}`);
  const objects = new Map(
    bundle.objects.map((object) => [object.contentHash, object]),
  );
  if (objects.size !== bundle.objects.length)
    throw new PoaError('EXPORT_INCOMPLETE', 'Export repeats an object hash');
  for (const required of bundle.requiredObjectHashes)
    if (!objects.has(required))
      throw new PoaError(
        'EXPORT_INCOMPLETE',
        'Required export object is absent',
      );
  for (const object of bundle.objects) {
    if (object.experimentId && object.experimentId !== bundle.experimentId)
      throw new PoaError('PROVENANCE_SPLICE', 'Export combines experiments');
    if (
      object.resultProvenance &&
      object.resultProvenance !== bundle.resultProvenance
    )
      throw new PoaError(
        'PROVENANCE_SPLICE',
        'Export combines provenance classes',
      );
  }
  const byType = (type: (typeof REQUIRED_EXPORT_TYPES)[number]) =>
    bundle.objects.find((object) => object.objectType === type)!;
  if (
    byType('FROZEN_POLICY').contentHash !== bundle.policyHash ||
    byType('FROZEN_CONFIGURATION').contentHash !== bundle.configurationHash ||
    byType('FROZEN_PROFILE').contentHash !== bundle.profileHash ||
    byType('ADAPTER_SET').contentHash !== bundle.adapterSetHash ||
    byType('PARSER_SET').contentHash !== bundle.parserSetHash
  )
    throw new PoaError('REPLAY_MISMATCH', 'Frozen experiment hashes differ');
  assertAuditContinuity(bundle.auditEvents);
  for (const event of bundle.auditEvents)
    if (!objects.has(event.contentHash))
      throw new PoaError('EXPORT_INCOMPLETE', 'Audit event object is absent');
  if (bundle.leaves.length !== bundle.auditEvents.length)
    throw new PoaError(
      'EXPORT_INCOMPLETE',
      'Export does not commit every audit event exactly once',
    );
  for (const [index, event] of bundle.auditEvents.entries()) {
    const leaf = bundle.leaves[index];
    if (
      !leaf ||
      contentHash(createLeaf(event)) !== contentHash(leaf) ||
      leaf.sequence !== event.sequence
    )
      throw new PoaError(
        'COMMITMENT_INVALID',
        'Committed leaf differs from audit event',
      );
  }
  assertBatchContinuity(bundle.batches);
  if (
    bundle.batches.at(-1)?.lastSequence !== bundle.auditEvents.at(-1)?.sequence
  )
    throw new PoaError(
      'EXPORT_INCOMPLETE',
      'Batch chain does not cover the complete audit sequence',
    );
  for (const batch of bundle.batches) {
    const leaves = bundle.leaves.filter(
      (leaf) =>
        BigInt(leaf.sequence) >= BigInt(batch.firstSequence) &&
        BigInt(leaf.sequence) <= BigInt(batch.lastSequence),
    );
    const expectedLeafCount =
      BigInt(batch.lastSequence) - BigInt(batch.firstSequence) + 1n;
    if (BigInt(leaves.length) !== expectedLeafCount)
      throw new PoaError(
        'BATCH_CONTINUITY',
        'Batch range does not contain every ordered leaf',
      );
    const leafSet = CommitmentLeafSet.parse({
      schemaVersion: 'proof-of-alpha/commitment-leaf-set/v1',
      batchId: batch.batchId,
      firstSequence: batch.firstSequence,
      lastSequence: batch.lastSequence,
      leaves,
    });
    if (
      contentHash(leafSet) !== batch.leavesObjectHash ||
      merkleRoot(leaves.map((leaf) => leaf.leafHash as Hex)) !== batch.root
    )
      throw new PoaError('COMMITMENT_INVALID', 'Batch leaf set differs');
    const proofs = bundle.proofs.filter(
      (proof) => proof.batchId === batch.batchId,
    );
    if (proofs.length !== leaves.length)
      throw new PoaError(
        'EXPORT_INCOMPLETE',
        'Batch does not include exactly one proof per leaf',
      );
    for (const [index, leaf] of leaves.entries()) {
      const matches = proofs.filter(
        (proof) => proof.leafHash === leaf.leafHash,
      );
      if (
        matches.length !== 1 ||
        matches[0]!.leafIndex !== index ||
        matches[0]!.leafCount !== leaves.length ||
        matches[0]!.root !== batch.root
      )
        throw new PoaError(
          'COMMITMENT_INVALID',
          'Batch proof does not bind its ordered leaf',
        );
      verifyProof(matches[0]!);
    }
    const receipts = bundle.registryReceipts.filter(
      (receipt) => receipt.batchId === batch.batchId,
    );
    if (receipts.length !== 1)
      throw new PoaError(
        'EXPORT_INCOMPLETE',
        'Batch does not include exactly one registry receipt',
      );
    verifyPublication(batch, receipts[0]!);
  }
  if (bundle.registryReceipts.length !== bundle.batches.length)
    throw new PoaError(
      'EXPORT_INCOMPLETE',
      'Export has an unbound registry receipt',
    );
  const selectedObject = objects.get(bundle.selectedResult.objectContentHash);
  const selectedEvent = bundle.auditEvents.find(
    (event) => event.sequence === bundle.selectedResult.auditSequence,
  );
  const selectedLeaf = bundle.leaves.find(
    (leaf) => leaf.leafHash === bundle.selectedResult.leafHash,
  );
  const selectedBatch = bundle.batches.find(
    (batch) => batch.batchId === bundle.selectedResult.batchId,
  );
  const selectedProof = bundle.proofs.find(
    (proof) =>
      proof.batchId === bundle.selectedResult.batchId &&
      proof.leafHash === bundle.selectedResult.leafHash,
  );
  const publication = bundle.registryReceipts.find(
    (receipt) => receipt.batchId === bundle.selectedResult.batchId,
  );
  if (
    !selectedObject ||
    !selectedEvent ||
    !selectedLeaf ||
    !selectedBatch ||
    !selectedProof ||
    !publication ||
    selectedEvent.contentHash !== selectedObject.contentHash ||
    selectedLeaf.contentHash !== selectedObject.contentHash ||
    selectedProof.root !== selectedBatch.root
  )
    throw new PoaError(
      'EXPORT_INCOMPLETE',
      'Selected result proof chain is incomplete',
    );
  verifyPublication(selectedBatch, publication);
  return {
    exportId: bundle.exportId,
    selectedObjectHash: selectedObject.contentHash,
    leafHash: selectedLeaf.leafHash,
    root: selectedBatch.root,
    batchHash: commitmentBatchHash(selectedBatch),
    transactionHash: publication.transactionHash,
  };
}

import { readFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { contentHash, PoaError } from '@poa/domain';
import {
  OperationsPolicy,
  DependencyManifest,
  InstrumentManifest,
  NetworkManifest,
  ProfileManifest,
  type ProfileData,
} from '@poa/schemas';

export const configFiles = [
  'networks.json',
  'instruments.json',
  'dependencies.json',
  'profiles.json',
] as const;
export const defaultConfigDir = resolve(
  dirname(fileURLToPath(import.meta.url)),
  '../../../config/v1',
);
export function parseBundle(
  raw: Record<(typeof configFiles)[number], unknown>,
) {
  const parsed = {
    networks: NetworkManifest.parse(raw['networks.json']),
    instruments: InstrumentManifest.parse(raw['instruments.json']),
    dependencies: DependencyManifest.parse(raw['dependencies.json']),
    profiles: ProfileManifest.parse(raw['profiles.json']),
  };
  const invalid = (message: string): never => {
    throw new PoaError('CONFIG_INVALID', message);
  };
  function unique<T>(items: T[], key: (item: T) => string) {
    const ids = items.map(key);
    if (new Set(ids).size !== ids.length)
      invalid('Duplicate manifest identifiers');
    return new Map(items.map((item) => [key(item), item]));
  }
  const networks = unique(parsed.networks.networks, (x) => x.networkId);
  const instruments = unique(
    parsed.instruments.instruments,
    (x) => x.instrumentId,
  );
  const dependencies = unique(
    parsed.dependencies.dependencies,
    (x) => x.dependencyId,
  );
  unique(parsed.profiles.profiles, (x) => x.profileId);
  const knownChains = parsed.networks.networks
    .filter((n) => n.chainId !== null)
    .map((n) => n.chainId);
  if (new Set(knownChains).size !== knownChains.length)
    invalid('Duplicate chain identities');
  for (const n of networks.values()) {
    unique(n.assets, (a) => a.assetId);
    if (
      n.verification.enabled &&
      n.verification.status !==
        (n.environment === 'mainnet'
          ? 'VERIFIED_FOR_FORWARD_SHADOW'
          : 'VERIFIED_FOR_TESTNET')
    )
      invalid('Network verification environment mismatch');
  }
  for (const i of instruments.values()) {
    const n = networks.get(i.networkId);
    if (!n || !n.assets.some((a) => a.assetId === i.assetId))
      throw new PoaError(
        'CONFIG_INVALID',
        `Unknown network/asset for ${i.instrumentId}`,
      );
    if (
      i.verification.enabled &&
      (!n.verification.enabled ||
        i.verification.status !== n.verification.status)
    )
      invalid(
        `Instrument environment or network not verified: ${i.instrumentId}`,
      );
    if (!dependencies.has(i.adapterId))
      invalid(`Missing adapter dependency: ${i.adapterId}`);
    if (
      i.verification.enabled &&
      !dependencies.get(i.adapterId)!.verification.enabled
    )
      invalid(`Instrument adapter not verified: ${i.adapterId}`);
  }
  for (const d of dependencies.values()) {
    if (d.networkIds.some((id) => !networks.has(id)))
      invalid(`Unknown dependency network: ${d.dependencyId}`);
    if (d.direction) {
      const source = networks.get(d.direction.source);
      const dest = networks.get(d.direction.destination);
      if (
        !source ||
        !dest ||
        source.networkId === dest.networkId ||
        source.environment !== dest.environment
      )
        throw new PoaError(
          'ENVIRONMENT_MISMATCH',
          `Incompatible route: ${d.dependencyId}`,
        );
      if (
        d.networkIds.length !== 2 ||
        !d.networkIds.includes(source.networkId) ||
        !d.networkIds.includes(dest.networkId)
      )
        invalid('Route/network binding mismatch');
      if (
        d.verification.enabled &&
        (!source.verification.enabled ||
          !dest.verification.enabled ||
          source.cctp.domain === null ||
          dest.cctp.domain === null ||
          source.cctp.domain === dest.cctp.domain ||
          !source.cctp.tokenMessenger ||
          !dest.cctp.messageTransmitter)
      )
        invalid('Route contracts/domains unresolved');
    }
    if (
      d.verification.enabled &&
      d.networkIds.some(
        (id) =>
          networks.get(id)!.environment !==
          (d.verification.status === 'VERIFIED_FOR_TESTNET'
            ? 'testnet'
            : 'mainnet'),
      )
    )
      invalid('Dependency verification environment mismatch');
  }
  for (const p of parsed.profiles.profiles) {
    if (
      new Set(p.marketNetworkIds).size !== p.marketNetworkIds.length ||
      new Set(p.instrumentAllowlist).size !== p.instrumentAllowlist.length ||
      new Set(p.requiredDependencyIds).size !== p.requiredDependencyIds.length
    )
      invalid('Duplicate profile references');
    if (
      !networks.has(p.registryNetworkId) ||
      p.marketNetworkIds.some((id) => !networks.has(id))
    )
      invalid('Unknown profile network');
    const expected =
      p.networkProfile === 'ETHEREUM_MAINNET_FORWARD'
        ? ['ethereum-mainnet']
        : p.networkProfile === 'CROSS_CHAIN_TESTNET'
          ? ['arc-testnet', 'ethereum-sepolia']
          : p.networkProfile === 'CROSS_CHAIN_MAINNET_FORWARD'
            ? ['arc-mainnet', 'ethereum-mainnet']
            : null;
    if (
      expected &&
      p.marketNetworkIds.slice().sort().join() !== expected.sort().join()
    )
      throw new PoaError(
        'ENVIRONMENT_MISMATCH',
        `Wrong markets for ${p.networkProfile}`,
      );
    if (
      expected &&
      p.marketNetworkIds.some(
        (id) =>
          networks.get(id)!.environment !==
          (p.networkProfile === 'CROSS_CHAIN_TESTNET' ? 'testnet' : 'mainnet'),
      )
    ) {
      throw new PoaError(
        'ENVIRONMENT_MISMATCH',
        `Market environment contradicts ${p.networkProfile}`,
      );
    }
    if (
      (p.networkProfile === 'CROSS_CHAIN_TESTNET' &&
        p.resultProvenance !== 'CROSS_CHAIN_TESTNET') ||
      (p.networkProfile === 'MIXED_DIAGNOSTIC' &&
        p.resultProvenance !== 'MIXED_DIAGNOSTIC') ||
      (p.networkProfile.endsWith('MAINNET_FORWARD') &&
        p.resultProvenance !== 'FORWARD_SHADOW')
    )
      invalid('Profile provenance mismatch');
    for (const id of p.instrumentAllowlist) {
      const i = instruments.get(id);
      if (
        !i ||
        !p.marketNetworkIds.includes(i.networkId) ||
        !p.requiredDependencyIds.includes(i.adapterId)
      )
        invalid(`Invalid allowlist/adapter binding: ${id}`);
    }
    for (const id of p.requiredDependencyIds) {
      const d = dependencies.get(id);
      if (
        !d ||
        d.networkIds.some(
          (id) =>
            !p.marketNetworkIds.includes(id) &&
            !(d.kind === 'REGISTRY' && id === p.registryNetworkId),
        )
      )
        invalid(`Dependency outside profile markets: ${id}`);
    }
    for (const a of p.initialDistribution) {
      const i = instruments.get(a.instrumentId);
      if (
        !i ||
        !p.instrumentAllowlist.includes(i.instrumentId) ||
        i.networkId !== a.networkId ||
        i.kind !== 'CASH' ||
        networks
          .get(i.networkId)
          ?.assets.find((asset) => asset.assetId === i.assetId)?.symbol !==
          'USDC'
      )
        invalid('Initial capital must be allowlisted USDC cash');
    }
    for (const ref of p.references)
      if (!p.instrumentAllowlist.includes(ref.instrumentId))
        invalid('Reference outside allowlist');
    const cashReference = instruments.get(p.references[0].instrumentId)!;
    if (
      networks
        .get(cashReference.networkId)
        ?.assets.find((asset) => asset.assetId === cashReference.assetId)
        ?.symbol !== 'USDC'
    )
      invalid('Cash reference must hold USDC');
    if (
      instruments.get(p.references[0].instrumentId)?.kind !== 'CASH' ||
      instruments.get(p.references[1].instrumentId)?.kind === 'CASH'
    )
      invalid('Require cash and yield references');
    if (
      (p.networkProfile === 'CROSS_CHAIN_TESTNET') !==
      (p.references[1].type === 'CONSERVATIVE_YIELD_TEST_REFERENCE')
    )
      invalid('Reference evidence label mismatch');
    for (const id of p.transfer.routeDependencyIds) {
      const d = dependencies.get(id);
      if (
        !d?.direction ||
        !p.requiredDependencyIds.includes(id) ||
        d.networkIds.some((id) => !p.marketNetworkIds.includes(id))
      )
        invalid('Transfer route outside frozen profile');
    }
    if (
      p.marketNetworkIds.length > 1 &&
      p.networkProfile !== 'MIXED_DIAGNOSTIC'
    ) {
      for (const source of p.marketNetworkIds)
        for (const destination of p.marketNetworkIds) {
          if (
            source !== destination &&
            !p.transfer.routeDependencyIds.some(
              (id) =>
                dependencies.get(id)?.direction?.source === source &&
                dependencies.get(id)?.direction?.destination === destination,
            )
          )
            invalid('Both transfer directions must be explicitly gated');
        }
    }
    if (p.enabled) {
      if (p.networkProfile === 'CROSS_CHAIN_MAINNET_FORWARD')
        invalid(
          'Cross-chain mainnet activation requires a new policy with a verified mainnet gas-funding convention',
        );
      if (
        p.marketNetworkIds.some(
          (id) => !networks.get(id)!.verification.enabled,
        ) ||
        p.instrumentAllowlist.some(
          (id) => !instruments.get(id)!.verification.enabled,
        ) ||
        p.requiredDependencyIds.some(
          (id) => !dependencies.get(id)!.verification.enabled,
        ) ||
        !networks.get(p.registryNetworkId)!.contracts.commitmentRegistry
      )
        invalid('Profile cannot activate unresolved dependencies');
      if (
        p.transfer.routeDependencyIds.length &&
        !p.transfer.shadowDelayModelVersion
      )
        invalid('Transfer profile needs a versioned delay model');
    }
  }
  return parsed;
}
export type ConfigBundle = ReturnType<typeof parseBundle>;
export function loadBundle(
  directory = process.env.POA_CONFIG_DIR ?? defaultConfigDir,
  verifyHash = true,
) {
  const raw = Object.fromEntries(
    configFiles.map((file) => [
      file,
      JSON.parse(readFileSync(join(directory, file), 'utf8')),
    ]),
  ) as Record<(typeof configFiles)[number], unknown>;
  const bundle = parseBundle(raw);
  const hashes = Object.fromEntries(
    configFiles.map((file) => [file, contentHash(raw[file])]),
  );
  const seal = {
    schemaVersion: 'proof-of-alpha/config-seal/v1',
    algorithm: 'KECCAK256_POA_CJSON_1',
    files: hashes,
    bundleHash: contentHash(hashes),
  };
  if (
    verifyHash &&
    contentHash(
      JSON.parse(readFileSync(join(directory, 'checksums.json'), 'utf8')),
    ) !== contentHash(seal)
  )
    throw new PoaError(
      'CONFIG_HASH_MISMATCH',
      'Manifest seal does not match. Create a new manifest version for material changes.',
    );
  return { bundle, seal };
}
export function profileReadiness(profile: ProfileData, bundle: ConfigBundle) {
  return {
    profileId: profile.profileId,
    networkProfile: profile.networkProfile,
    resultProvenance: profile.resultProvenance,
    enabled: profile.enabled,
    realCapitalEligibilityEnabled: false as const,
    blockers: [
      ...(!profile.enabled ? ['PROFILE_DISABLED'] : []),
      ...bundle.networks.networks
        .filter(
          (n) =>
            [...profile.marketNetworkIds, profile.registryNetworkId].includes(
              n.networkId,
            ) && !n.verification.enabled,
        )
        .map((n) => `network:${n.networkId}`),
      ...bundle.instruments.instruments
        .filter(
          (i) =>
            profile.instrumentAllowlist.includes(i.instrumentId) &&
            !i.verification.enabled,
        )
        .map((i) => `instrument:${i.instrumentId}`),
      ...bundle.dependencies.dependencies
        .filter(
          (d) =>
            profile.requiredDependencyIds.includes(d.dependencyId) &&
            !d.verification.enabled,
        )
        .map((d) => `dependency:${d.dependencyId}`),
    ],
    limitations: profile.limitations,
  };
}
export function requireDependency(bundle: ConfigBundle, dependencyId: string) {
  const dep = bundle.dependencies.dependencies.find(
    (d) => d.dependencyId === dependencyId,
  );
  if (!dep || !dep.verification.enabled)
    throw new PoaError(
      'DEPENDENCY_UNVERIFIED',
      `External dependency ${dependencyId} is disabled`,
    );
  return dep;
}
export function catalog() {
  const { bundle, seal } = loadBundle();
  return {
    milestone: 'M3' as const,
    experimentStartAvailable: false as const,
    automaticFundingEnabled: false as const,
    bundleHash: seal.bundleHash,
    profiles: bundle.profiles.profiles.map((p) => profileReadiness(p, bundle)),
  };
}

export function loadOperationsPolicy() {
  return OperationsPolicy.parse(
    JSON.parse(
      readFileSync(join(defaultConfigDir, '../operations-v1.json'), 'utf8'),
    ),
  );
}

