  DemoDiagnostic,
  type DemoDiagnosticData,
  type ShadowPortfolioData,
} from '@poa/schemas';

const sizes = [
  {
    id: 'capital-1k',
    capital: '1000000000',
    invested: '400000000',
    transfer: '200000000',
    gas: '3100000',
    failedGas: '1400000',
