  z.strictObject({
    ...base,
    ...costs,
    kind: z.literal('COST'),
    status: z.literal('FAILED_AFTER_ATTEMPT'),
    reasonCode: z.string().min(1),
  }),
  z.strictObject({
    ...base,
    ...costs,
    kind: z.literal('APPROVE'),
    allowanceId: Id,
    networkId: Id,
    assetId: Id,
    spenderId: Id,
    amountMinor: UInt,
  }),
  z.strictObject({
    ...base,
    ...costs,
    kind: z.literal('DEPOSIT'),
    cashViewId: Id,
    positionId: Id,
    instrumentId: Id,
    sharesCreditMinor: PositiveUInt,
    indexNumerator: PositiveUInt,
    indexDenominator: PositiveUInt,
    inputUsdcMinor: PositiveUInt,
  }),
  z.strictObject({
    ...base,
    ...costs,
    kind: z.literal('WITHDRAW'),
    cashViewId: Id,
    positionId: Id,
    sharesDebitMinor: PositiveUInt,
    cashCreditUsdcMinor: UInt,
  }),
  z.strictObject({
