export const Erc4626Payload = z
  .strictObject({
    schemaVersion: z.literal('proof-of-alpha/erc4626-state/v1'),
    chainId: z.enum(['1', '11155111', '5042002']),
    family: z.enum(['MORPHO_METAMORPHO_V1', 'POA_FINITE_TEST_VAULT_V1']),
    vault: Address,
