export const DashboardScenario = z.strictObject({
  scenarioId: Id,
  initialAmountUsdcMinor: z.enum(['1000000000', '10000000000', '100000000000']),
  checkpoint: ScenarioCheckpoint,
  descriptiveEvaluation: ScenarioEvaluation,
