export const EvidenceKind = z.enum([
  'OFFICIAL_SOURCE',
  'ONCHAIN_CODE',
  'FIXED_BLOCK_FORK',
  'ARCHIVE_READ',
  'LIVE_ROUND_TRIP',
  'FEE_CAPTURE',
  'GAS_CALIBRATION',
  'FINALITY',
  'REPLAY',
