const total = (items: readonly string[]) =>
  items.reduce((sum, value) => sum + BigInt(value), 0n);
const signedBps = (value: bigint, initial: bigint) =>
  (((value - initial) * 10_000n) / initial).toString();

function metrics(
  item: CheckpointPortfolioData,
  priorMarks: readonly string[],
): DescriptivePortfolioMetricsData {
  const initial = BigInt(item.portfolio.initialValueUsdcMinor);
  const mark = item.valuation.markValueUsdcMinor;
  const peak =
    mark === null
      ? null
      : [BigInt(mark), ...priorMarks.map(BigInt)].reduce((a, b) =>
          a > b ? a : b,
        );
  const drawdown =
    mark === null || peak === null || peak === 0n
      ? null
      : (((peak - BigInt(mark)) * 10_000n) / peak).toString();
  return {
    initialValueUsdcMinor: initial.toString(),
    markValueUsdcMinor: mark,
    liquidationValueUsdcMinor: item.valuation.liquidationValueUsdcMinor,
    pnlMarkUsdcMinor:
      mark === null ? null : (BigInt(mark) - initial).toString(),
    returnMarkBps: mark === null ? null : signedBps(BigInt(mark), initial),
    availableUsdcMinor: item.valuation.availableUsdcMinor,
    investedMarkUsdcMinor: portfolioPositionMark(item),
    reservedUsdcMinor: item.valuation.reservedUsdcMinor,
    inTransitUsdcMinor: item.valuation.inTransitUsdcMinor,
    blockedValueUsdcMinor: item.valuation.blockedValueUsdcMinor,
    cumulativeCostsUsdcMinor: total(
      item.portfolio.recognizedCosts.map((cost) => cost.amountUsdcMinor),
    ).toString(),
    drawdownMarkBps: drawdown,
    dataQuality: item.valuation.dataQuality,
    reasonCodes: item.valuation.reasonCodes,
  };
}

const difference = (left: string | null, right: string | null) =>
  left === null || right === null
    ? null
    : (BigInt(left) - BigInt(right)).toString();

export function evaluateScenario(
  checkpointInput: ScenarioCheckpointData,
  priorAgentMarksUsdcMinor: readonly string[] = [],
): ScenarioEvaluationData {
  const checkpoint = ScenarioCheckpoint.parse(checkpointInput);
  const agent = metrics(checkpoint.agent, priorAgentMarksUsdcMinor);
  const cash = metrics(checkpoint.cashReference, []);
  const conservative = metrics(checkpoint.conservativeYieldReference, []);
  const yieldAvailable =
    checkpoint.conservativeYieldReference.comparisonAvailable &&
    conservative.markValueUsdcMinor !== null;
  const body = {
    schemaVersion: 'proof-of-alpha/scenario-evaluation/v1' as const,
    evaluationId: `${checkpoint.checkpointId}-evaluation`,
    checkpointId: checkpoint.checkpointId,
    experimentId: checkpoint.experimentId,
    scenarioId: checkpoint.scenarioId,
    checkpointAt: checkpoint.checkpointAt,
    resultProvenance: checkpoint.resultProvenance,
    valuationConvention: 'MARK_AND_LIQUIDATION_ESTIMATE' as const,
    agent,
    cashReference: cash,
    conservativeYieldReference: conservative,
    differenceVsCashMarkUsdcMinor: difference(
      agent.markValueUsdcMinor,
      cash.markValueUsdcMinor,
    ),
    differenceVsConservativeYieldMarkUsdcMinor: yieldAvailable
      ? difference(agent.markValueUsdcMinor, conservative.markValueUsdcMinor)
      : null,
    excessReturnVsCashBps: difference(agent.returnMarkBps, cash.returnMarkBps),
    excessReturnVsConservativeYieldBps: yieldAvailable
      ? difference(agent.returnMarkBps, conservative.returnMarkBps)
      : null,
    comparisonAvailability: {
      cash: true as const,
      conservativeYield: yieldAvailable,
    },
    capitalScenarioRelationship: 'CORRELATED_POLICY_VIEWS' as const,
    effectiveIndependentSampleCount: '1' as const,
    statisticalStatus: 'NOT_ASSESSED' as const,
    statisticalReasonCodes: ['INFERENCE_DISABLED'] as ['INFERENCE_DISABLED'],
    realCapitalEligibility: 'NOT_ELIGIBLE_FOR_REAL_CAPITAL' as const,
    eligibilityReasonCodes: [
      `PROVENANCE_${checkpoint.resultProvenance}`,
      'AUTOMATIC_FUNDING_DISABLED',
    ],
  };
  return ScenarioEvaluation.parse({
    ...body,
    evaluationHash: contentHash(body),
  });
}

export interface EligibilityInput {
  experimentId: string;
  scenarioId: string;
  policyHash: `0x${string}`;
  checkpointHash: `0x${string}`;
  resultProvenance: ProvenanceData;
  networkProfile: NetworkProfileData;
  operationalStatus: 'COMPLIANT' | 'VIOLATION' | 'UNASSESSABLE';
  economicStatus: 'CRITERIA_MET' | 'CRITERIA_NOT_MET' | 'UNASSESSABLE';
  statisticalStatus:
    | 'NOT_ASSESSED'
    | 'INSUFFICIENT_EVIDENCE'
    | 'CRITERION_NOT_MET'
    | 'CRITERION_MET';
  statisticalMethodVersion: string | null;
  dimensionReasonCodes?: readonly string[];
  supersedesHash?: `0x${string}` | null;
}

/** Applies the immutable provenance exclusion before any policy criterion.
 * The result describes eligibility only; it never authorizes funding. */
export function evaluateEligibility(input: EligibilityInput) {
  const excluded =
    input.resultProvenance !== 'FORWARD_SHADOW' ||
    !['ETHEREUM_MAINNET_FORWARD', 'CROSS_CHAIN_MAINNET_FORWARD'].includes(
      input.networkProfile,
    );
  let overallStatus:
    | 'NOT_ELIGIBLE_FOR_REAL_CAPITAL'
    | 'UNASSESSABLE'
    | 'CRITERIA_NOT_MET'
    | 'INSUFFICIENT_EVIDENCE'
    | 'ELIGIBLE_UNDER_POLICY';
  const reasons = [...(input.dimensionReasonCodes ?? [])];
  if (excluded) {
    overallStatus = 'NOT_ELIGIBLE_FOR_REAL_CAPITAL';
    reasons.unshift(`PROVENANCE_${input.resultProvenance}`);
  } else if (
    input.operationalStatus === 'UNASSESSABLE' ||
    input.economicStatus === 'UNASSESSABLE'
  ) {
    overallStatus = 'UNASSESSABLE';
    reasons.unshift('REQUIRED_EVIDENCE_UNASSESSABLE');
  } else if (
    input.operationalStatus === 'VIOLATION' ||
    input.economicStatus === 'CRITERIA_NOT_MET' ||
    input.statisticalStatus === 'CRITERION_NOT_MET'
  ) {
    overallStatus = 'CRITERIA_NOT_MET';
    reasons.unshift('POLICY_CRITERION_NOT_MET');
  } else if (
    !input.statisticalMethodVersion ||
    input.statisticalStatus === 'NOT_ASSESSED' ||
    input.statisticalStatus === 'INSUFFICIENT_EVIDENCE'
  ) {
    overallStatus = 'INSUFFICIENT_EVIDENCE';
    reasons.unshift(
      input.statisticalStatus === 'NOT_ASSESSED'
        ? 'INFERENCE_DISABLED'
        : 'INSUFFICIENT_STATISTICAL_EVIDENCE',
    );
  } else {
    overallStatus = 'ELIGIBLE_UNDER_POLICY';
    reasons.unshift('ALL_FROZEN_CRITERIA_MET');
  }
  reasons.push('AUTOMATIC_FUNDING_DISABLED');
  return EvaluationReceipt.parse({
    schemaVersion: 'proof-of-alpha/evaluation-receipt/v1',
    experimentId: input.experimentId,
    scenarioId: input.scenarioId,
    policyHash: input.policyHash,
    checkpointHash: input.checkpointHash,
    resultProvenance: input.resultProvenance,
    networkProfile: input.networkProfile,
    operationalStatus: input.operationalStatus,
    economicStatus: input.economicStatus,
    statisticalStatus: input.statisticalStatus,
    statisticalMethodVersion: input.statisticalMethodVersion,
    overallStatus,
    reasonCodes: [...new Set(reasons)],
    supersedesHash: input.supersedesHash ?? null,
    automaticFundingEnabled: false,
  });
}

export function replayM4(input: M4ReplayBundleData) {
  const bundle = M4ReplayBundle.parse(input);
  for (const object of bundle.rawObjects) {
    const actual = rawBytesHash(
      Uint8Array.from(Buffer.from(object.bytesHex, 'hex')),
    );
    if (object.objectKey !== `raw/keccak256/${actual}`)
      throw new PoaError(
        'ARCHIVE_INTEGRITY',
        'M4 raw input content address differs',
      );
  }
  if (
    bundle.rawObjects.length &&
    contentHash(bundle.rawObjects) !== bundle.checkpoint.observationSetHash
  )
    throw new PoaError(
      'REPLAY_MISMATCH',
      'M4 observation set differs from archived inputs',
    );
  const expectedQuoteHash = contentHash({
    scenarioId: bundle.checkpoint.scenarioId,
    amountUsdcMinor: bundle.checkpoint.agent.portfolio.initialValueUsdcMinor,
    objectKeys: bundle.rawObjects.map((object) => object.objectKey),
  });
  if (
    bundle.rawObjects.length &&
    expectedQuoteHash !== bundle.checkpoint.amountQuoteHash
  )
    throw new PoaError(
      'REPLAY_MISMATCH',
      'M4 amount-specific quote set differs',
    );
  const archivedHashes = new Set(
    bundle.rawObjects.map((object) => object.objectKey.split('/').at(-1)),
  );
  if (
    bundle.checkpointInputs &&
    [
      bundle.checkpointInputs.agent,
      bundle.checkpointInputs.cashReference,
      bundle.checkpointInputs.conservativeYieldReference,
    ]
      .flatMap((item) => [
        ...item.accruals.map((value) => value.sourceHash),
        ...item.valuations.map((value) => value.sourceHash),
      ])
      .some((sourceHash) => !archivedHashes.has(sourceHash))
  )
    throw new PoaError(
      'ARCHIVE_INTEGRITY',
      'Checkpoint input source is absent from the raw archive',
    );
  const checkpoint = bundle.checkpointInputs
    ? createScenarioCheckpoint({
        checkpointId: bundle.checkpoint.checkpointId,
        sequence: bundle.checkpoint.sequence,
        checkpointAt: bundle.checkpoint.checkpointAt,
        observationSetHash: bundle.checkpoint.observationSetHash,
        amountQuoteHash: bundle.checkpoint.amountQuoteHash,
        agent: checkpointPortfolio({
          checkpointId: bundle.checkpoint.checkpointId,
          ...bundle.checkpointInputs.agent,
        }),
        cashReference: checkpointPortfolio({
          checkpointId: bundle.checkpoint.checkpointId,
          ...bundle.checkpointInputs.cashReference,
        }),
        conservativeYieldReference: checkpointPortfolio({
          checkpointId: bundle.checkpoint.checkpointId,
          ...bundle.checkpointInputs.conservativeYieldReference,
        }),
      })
    : ScenarioCheckpoint.parse({
        ...bundle.checkpoint,
        checkpointHash: contentHash(bundle.checkpoint),
      });
  if (checkpoint.checkpointHash !== bundle.expectedCheckpointHash)
    throw new PoaError(
      'REPLAY_MISMATCH',
      'M4 checkpoint hash differs from archived result',
    );
  const evaluation = evaluateScenario(
    checkpoint,
    bundle.priorAgentMarksUsdcMinor,
  );
  if (evaluation.evaluationHash !== bundle.expectedEvaluation.evaluationHash)
    throw new PoaError(
      'REPLAY_MISMATCH',
      'M4 evaluation differs from archived result',
    );
  return { checkpoint, evaluation };
}

import { PoaError } from '@poa/domain';
import {
  ActionIntent,
  ExecutionPlan,
  ExperimentPolicy,
  ShadowPortfolio,
  type ActionIntentData,
  type ExperimentPolicyData,
  type ProfileData,
  type ShadowPortfolioData,
} from '@poa/schemas';

export const PLANNER_VERSION = '1.0.0';

export interface PlannerContext {
  actionId: string;
  receivedAt: string;
  profile: ProfileData;
  assetAddresses: Readonly<Record<string, string>>;
}

export function planAllocation(
  policyInput: ExperimentPolicyData,
  portfolioInput: ShadowPortfolioData,
  intentInput: ActionIntentData,
  context: PlannerContext,
) {
  const policy = ExperimentPolicy.parse(policyInput);
  const portfolio = ShadowPortfolio.parse(portfolioInput);
  const intent = ActionIntent.parse(intentInput);
  if (
    intent.experimentId !== policy.experimentId ||
    intent.experimentId !== portfolio.experimentId ||
    intent.capitalScenarioId !== portfolio.scenarioId ||
    intent.policyHash === undefined ||
    intent.networkProfile !== policy.networkProfile
  )
    throw new PoaError('POLICY_VIOLATION', 'Planner input binding mismatch');
  if (
    intent.maxSlippageBps > context.profile.constraints.maximumSwapSlippageBps
  )
    throw new PoaError('POLICY_VIOLATION', 'Slippage bound exceeds policy');
  for (const target of intent.targetAllocation) {
    if (!context.profile.instrumentAllowlist.includes(target.instrumentId))
      throw new PoaError(
        'UNSUPPORTED_INSTRUMENT',
        `Instrument is outside frozen allowlist: ${target.instrumentId}`,
      );
    if (!context.profile.marketNetworkIds.includes(target.networkId))
      throw new PoaError(
        'ENVIRONMENT_MISMATCH',
        'Target network is outside profile',
      );
    if (
      !target.instrumentId.includes('cash') &&
      target.weightBps > context.profile.constraints.maximumInstrumentWeightBps
    )
      throw new PoaError(
        'POLICY_VIOLATION',
        'Investment concentration exceeds policy',
      );
  }
  const cashWeight = intent.targetAllocation
    .filter((x) => x.instrumentId.includes('cash'))
    .reduce((sum, x) => sum + x.weightBps, 0);
  if (cashWeight < context.profile.constraints.minimumTargetAvailableCashBps)
    throw new PoaError(
      'POLICY_VIOLATION',
      'Target cash reserve is below policy',
    );

  const invested = intent.targetAllocation.filter(
    (x) => !x.instrumentId.includes('cash'),
  );
  if (invested.length !== 1 || invested[0]!.instrumentId !== 'eth-aave-usdc')
    throw new PoaError(
      'UNSUPPORTED_INSTRUMENT',
      'M3 planner supports the archived Ethereum Aave USDC slice only',
    );
  const target = invested[0]!;
  const amount =
    (BigInt(portfolio.initialValueUsdcMinor) * BigInt(target.weightBps)) /
    10000n;
  if (amount <= 0n)
    throw new PoaError('POLICY_VIOLATION', 'Derived deposit must be positive');
  if (BigInt(intent.maxCostUsdcMinor) === 0n)
    throw new PoaError(
      'POLICY_VIOLATION',
      'Execution requires a positive cost bound',
    );
  const address = context.assetAddresses['ethereum-mainnet/usdc'];
  if (!address)
    throw new PoaError(
      'DATA_UNAVAILABLE',
      'Frozen USDC asset identity is missing',
    );
  const amountObject = {
    networkId: 'ethereum-mainnet',
    assetId: 'usdc',
    assetAddress: address,
    decimals: 6,
    minor: amount.toString(),
  };
  return ExecutionPlan.parse({
    schemaVersion: 'proof-of-alpha/execution-plan/v1',
    experimentId: policy.experimentId,
    scenarioId: portfolio.scenarioId,
    actionId: context.actionId,
    policyHash: intent.policyHash,
    portfolioVersion: portfolio.version,
    plannerVersion: PLANNER_VERSION,
    receivedAt: context.receivedAt,
    resultProvenance: policy.resultProvenance,
    steps: [
      {
        operationId: `${context.actionId}-approve`,
        kind: 'APPROVE',
        networkId: 'ethereum-mainnet',
        instrumentId: 'eth-aave-usdc',
        dependsOn: [],
        input: amountObject,
        maxCostUsdcMinor: intent.maxCostUsdcMinor,
      },
      {
        operationId: `${context.actionId}-deposit`,
        kind: 'DEPOSIT',
        networkId: 'ethereum-mainnet',
        instrumentId: 'eth-aave-usdc',
        dependsOn: [`${context.actionId}-approve`],
        input: amountObject,
        maxCostUsdcMinor: intent.maxCostUsdcMinor,
      },
    ],
  });
}

import { applyReceipt } from '@poa/accounting';
import { aaveSupply, type ReceiptContext } from '@poa/adapters';
import { contentHash, PoaError } from '@poa/domain';
import type { ObjectArchive } from '@poa/market-data';
import {
  EconomicReplayBundle,
  type EconomicReplayBundleData,
  type ArchivedObservationData,
} from '@poa/schemas';

export * from './m3.js';
export * from './m4.js';

function field(input: Record<string, string | boolean>, key: string) {
  const value = input[key];
  if (typeof value !== 'string')
    throw new PoaError(
      'INVALID_SCHEMA',
      `Replay input ${key} must be a string`,
    );
  return value;
}

function observation(
  map: Map<string, ArchivedObservationData>,
  id: string | undefined,
) {
  const value = id ? map.get(id) : undefined;
  if (!value)
    throw new PoaError(
      'DATA_UNAVAILABLE',
      `Replay observation missing: ${id ?? '<unset>'}`,
    );
  return value;
}

export async function replayEconomicBundle(
  archive: ObjectArchive,
  input: EconomicReplayBundleData,
  verifyExpected = true,
) {
  const bundle = EconomicReplayBundle.parse(input);
  const observations = new Map(
    bundle.observations.map((item) => [item.observationId, item]),
  );
  let state = bundle.initialPortfolio;
  for (const step of bundle.steps) {
    const context: ReceiptContext = {
      experimentId: state.experimentId,
      scenarioId: state.scenarioId,
      expectedPortfolioVersion: state.version,
      observedAt: field(step.input, 'observedAt'),
      evaluationTime: field(step.input, 'evaluationTime'),
      resultProvenance: state.resultProvenance,
      cashViewId: field(step.input, 'cashViewId'),
      cashBalanceFamilyId: field(step.input, 'cashBalanceFamilyId'),
    };
    if (step.operation !== 'AAVE_SUPPLY')
      throw new PoaError(
        'INVALID_SCHEMA',
        `Replay operation is not implemented: ${step.operation}`,
      );
    const result = await aaveSupply(archive, context, {
      amountMinor: field(step.input, 'amountMinor'),
      instrumentId: field(step.input, 'instrumentId'),
      positionId: field(step.input, 'positionId'),
      allowanceId: field(step.input, 'allowanceId'),
      currentAllowanceMinor: field(step.input, 'currentAllowanceMinor'),
      reserve: observation(observations, step.observationIds[0]),
      approvalGas: observation(observations, step.observationIds[1]),
      supplyGas: observation(observations, step.observationIds[2]),
      conversion: observation(observations, step.observationIds[3]),
    });
    for (const receipt of result.receipts) state = applyReceipt(state, receipt);
  }
  const finalPortfolioHash = contentHash(state);
  if (
    verifyExpected &&
    finalPortfolioHash !== bundle.expectedFinalPortfolioHash
  )
    throw new PoaError(
      'REPLAY_MISMATCH',
      `Replay hash ${finalPortfolioHash} differs from ${bundle.expectedFinalPortfolioHash}`,
    );
  return { state, finalPortfolioHash };
}

export * from './m7.js';

import { aaveSupply } from '@poa/adapters';
import { contentHash, PoaError } from '@poa/domain';
import { planAllocation } from '@poa/execution';
import {
  archiveJson,
  createObservation,
  MemoryObjectArchive,
} from '@poa/market-data';
import {
  AaveReservePayload,
  EthUsdcConversionPayload,
  GasPayload,
  type ActionEnvelopeData,
  type ArchivedObservationData,
  type ExperimentPolicyData,
  type ProfileData,
  type ShadowPortfolioData,
} from '@poa/schemas';

const address = (digit: string) => `0x${digit.repeat(40)}`;

export interface M3ExecutionInput {
  actionId: string;
  envelope: ActionEnvelopeData;
  policy: ExperimentPolicyData;
  portfolio: ShadowPortfolioData;
  receivedAt: string;
  profile: ProfileData;
  usdcAddress: string;
}

export async function prepareSyntheticM3Execution(input: M3ExecutionInput) {
  if (input.policy.resultProvenance !== 'SYNTHETIC_TEST')
    throw new Error('Synthetic M3 executor refuses non-synthetic provenance');
  const plan = planAllocation(
    input.policy,
    input.portfolio,
    input.envelope.request.intent,
    {
      actionId: input.actionId,
      receivedAt: input.receivedAt,
      profile: input.profile,
      assetAddresses: { 'ethereum-mainnet/usdc': input.usdcAddress },
    },
  );
  const observedAt = new Date(
    Math.max(
      Date.parse(input.receivedAt) +
        input.profile.execution.firstEthereumStepBlockOffset * 1000,
      Date.parse(input.portfolio.lastAppliedAt ?? input.receivedAt) +
        input.profile.execution.nextEthereumStepBlockOffset * 1000,
    ),
  ).toISOString();
  const amount = plan.steps.at(-1)!.input.minor;
  const amountSize = BigInt(amount);
  const archive = new MemoryObjectArchive();
  const expiresAt = new Date(Date.parse(input.receivedAt) + 600_000)
    .toISOString()
    .replace(/\.\d{3}Z$/, '.000Z');
  async function capture(
    id: string,
    payload: unknown,
  ): Promise<ArchivedObservationData> {
    const rawObject = await archiveJson(archive, payload, observedAt);
    return createObservation({
      observationId: `${input.actionId}-${id}`,
      sourceId: `synthetic-m3-${id}`,
      sourceVersion: '1.0.0',
      parserVersion: '1.0.0',
      adapterVersion: '1.0.0',
      requestedAt: input.receivedAt,
      observedAt,
      expiresAt,
      block: null,
      rawObject,
      resultProvenance: 'SYNTHETIC_TEST',
    });
  }
  const reserve = await capture(
    'reserve',
    AaveReservePayload.parse({
      schemaVersion: 'proof-of-alpha/aave-v3-reserve/v1',
      chainId: '1',
      pool: address('1'),
      underlying: address('2'),
      aToken: address('3'),
      assetId: 'usdc',
      decimals: 6,
      active: true,
      frozen: false,
      paused: false,
      supplyCapMinor: '1000000000000000',
      totalSuppliedMinor: '500000000000000',
      availableLiquidityMinor: '500000000000000',
      liquidityIndexRay: '1000000000000000000000000000',
    }),
  );
  const approvalGas = await capture(
    'approval-gas',
    GasPayload.parse({
      schemaVersion: 'proof-of-alpha/gas-input/v1',
      operation: 'APPROVE',
      amountInMinor: amount,
      gasUnits: (50_000n + amountSize / 100_000_000n).toString(),
      effectiveGasPriceWei: '20000000000',
    }),
  );
  const supplyGas = await capture(
    'supply-gas',
    GasPayload.parse({
      schemaVersion: 'proof-of-alpha/gas-input/v1',
      operation: 'SUPPLY',
      amountInMinor: amount,
      gasUnits: (140_000n + amountSize / 10_000_000n).toString(),
      effectiveGasPriceWei: '20000000000',
    }),
  );
  const conversion = await capture(
    'conversion',
    EthUsdcConversionPayload.parse({
      schemaVersion: 'proof-of-alpha/eth-usdc-conversion/v1',
      usdcMinorNumerator: '3000000000',
      weiDenominator: '1000000000000000000',
      roundId: `${input.actionId}-synthetic`,
      answerUpdatedAt: observedAt,
      heartbeatSeconds: '3600',
    }),
  );
  const result = await aaveSupply(
    archive,
    {
      experimentId: input.policy.experimentId,
      scenarioId: input.portfolio.scenarioId,
      expectedPortfolioVersion: input.portfolio.version,
      observedAt,
      evaluationTime: observedAt,
      resultProvenance: 'SYNTHETIC_TEST',
      cashViewId: 'eth-usdc-view',
      cashBalanceFamilyId: 'eth-usdc-family',
    },
    {
      amountMinor: amount,
      instrumentId: 'eth-aave-usdc',
      positionId: `${input.actionId}-position`,
      allowanceId: `${input.actionId}-allowance`,
      currentAllowanceMinor: '0',
      reserve,
      approvalGas,
      supplyGas,
      conversion,
      operationPrefix: input.actionId,
    },
  );
  const receiptTimes = result.receipts.map((_, index) =>
    new Date(
      Date.parse(observedAt) +
        index * input.profile.execution.nextEthereumStepBlockOffset * 1000,
    ).toISOString(),
  );
  result.receipts.forEach((receipt, index) => {
    receipt.observedAt = receiptTimes[index]!;
  });
  const totalCost = result.receipts
    .flatMap((receipt) => ('costs' in receipt ? receipt.costs : []))
    .reduce((sum, cost) => sum + BigInt(cost.amountUsdcMinor), 0n);
  if (totalCost > BigInt(input.envelope.request.intent.maxCostUsdcMinor))
    throw new PoaError(
      'POLICY_VIOLATION',
      'Archived execution cost exceeds signed maximum',
    );
  const rawObjects = [...archive.objects.entries()]
    .sort(([a], [b]) => a.localeCompare(b))
    .map(([objectKey, bytes]) => ({
      objectKey,
      bytesHex: Buffer.from(bytes).toString('hex'),
    }));
  return {
    plan,
    receipts: result.receipts,
    syntheticInputBundle: {
      schemaVersion: 'proof-of-alpha/m3-synthetic-input-bundle/v1',
      resultProvenance: 'SYNTHETIC_TEST',
      timing: {
        rule: 'SYNTHETIC_ONE_SECOND_PER_BLOCK_OFFSET',
        receivedAt: input.receivedAt,
        receiptTimes,
      },
      observations: [reserve, approvalGas, supplyGas, conversion],
      rawObjects,
      adapterResultHash: result.sourceHash,
      totalCostUsdcMinor: totalCost.toString(),
      expectedReceiptsHash: contentHash(result.receipts),
      replay: {
        experimentId: input.policy.experimentId,
        scenarioId: input.portfolio.scenarioId,
        expectedPortfolioVersion: input.portfolio.version,
        observedAt,
        amountMinor: amount,
        instrumentId: 'eth-aave-usdc',
        positionId: `${input.actionId}-position`,
        allowanceId: `${input.actionId}-allowance`,
        operationPrefix: input.actionId,
      },
    },
  };
}

export async function replaySyntheticM3Bundle(bundle: any) {
  if (
    bundle?.schemaVersion !== 'proof-of-alpha/m3-synthetic-input-bundle/v1' ||
    bundle.resultProvenance !== 'SYNTHETIC_TEST'
  )
    throw new PoaError('INVALID_SCHEMA', 'Not an M3 synthetic replay bundle');
  const archive = new MemoryObjectArchive();
  for (const object of bundle.rawObjects ?? [])
    await archive.putIfAbsent(
      object.objectKey,
      Uint8Array.from(Buffer.from(object.bytesHex, 'hex')),
    );
  const find = (suffix: string) => {
    const value = (bundle.observations as ArchivedObservationData[]).find((x) =>
      x.observationId.endsWith(suffix),
    );
    if (!value)
      throw new PoaError(
        'DATA_UNAVAILABLE',
        `Replay observation missing: ${suffix}`,
      );
    return value;
  };
  const replay = bundle.replay;
  const result = await aaveSupply(
    archive,
    {
      experimentId: replay.experimentId,
      scenarioId: replay.scenarioId,
      expectedPortfolioVersion: replay.expectedPortfolioVersion,
      observedAt: replay.observedAt,
      evaluationTime: replay.observedAt,
      resultProvenance: 'SYNTHETIC_TEST',
      cashViewId: 'eth-usdc-view',
      cashBalanceFamilyId: 'eth-usdc-family',
    },
    {
      amountMinor: replay.amountMinor,
      instrumentId: replay.instrumentId,
      positionId: replay.positionId,
      allowanceId: replay.allowanceId,
      currentAllowanceMinor: '0',
      reserve: find('-reserve'),
      approvalGas: find('-approval-gas'),
      supplyGas: find('-supply-gas'),
      conversion: find('-conversion'),
      operationPrefix: replay.operationPrefix,
    },
  );
  if (bundle.timing)
    result.receipts.forEach((receipt, index) => {
      const at = bundle.timing.receiptTimes[index];
      if (
        typeof at !== 'string' ||
        Date.parse(at) <= Date.parse(bundle.timing.receivedAt)
      )
        throw new PoaError(
          'REPLAY_MISMATCH',
          'Invalid synthetic prospective timing',
        );
      receipt.observedAt = at;
    });
  const receiptsHash = contentHash(result.receipts);
  if (receiptsHash !== bundle.expectedReceiptsHash)
    throw new PoaError(
      'REPLAY_MISMATCH',
      'M3 receipt replay differs from archived result',
    );
  return { receipts: result.receipts, receiptsHash };
}

import { mulDiv } from '@poa/accounting';
