export function buildDemoDiagnostic(
  kind: DemoDiagnosticData['kind'],
): DemoDiagnosticData {
  const rawInputs: DemoDiagnosticData['rawInputs'] = [];
  const scenarios = sizes.map((size) => {
    const initial = createPortfolio({
      experimentId:
        kind === 'LONGER_REPLAY'
