  });
}

export function replayDemoDiagnostic(input: unknown) {
  const bundle = DemoDiagnostic.parse(input);
  const raw = new Map(bundle.rawInputs.map((o) => [o.contentHash, o.payload]));
  if (raw.size !== bundle.rawInputs.length)
    throw new PoaError('ARCHIVE_INTEGRITY', 'Duplicate diagnostic source');
  for (const object of bundle.rawInputs)
    if (contentHash(object.payload) !== object.contentHash)
      throw new PoaError('ARCHIVE_INTEGRITY', 'Diagnostic raw input changed');
  if (
    bundle.presentationProvenance !==
    (bundle.kind === 'LONGER_REPLAY' ? 'HISTORICAL_REPLAY' : 'SYNTHETIC_TEST')
  )
    throw new PoaError(
      'PROVENANCE_SPLICE',
      'Diagnostic presentation provenance changed',
    );
  const output = bundle.scenarios.map((scenario) => {
    let state = assertPortfolio(scenario.initial);
    if (state.resultProvenance !== 'SYNTHETIC_TEST')
      throw new PoaError(
        'PROVENANCE_SPLICE',
        'Synthetic input cannot become forward history',
      );
    const snapshots: { at: string; portfolio: ShadowPortfolioData }[] = [];
    for (const receipt of scenario.receipts) {
      if (receipt.resultProvenance !== state.resultProvenance)
        throw new PoaError('PROVENANCE_SPLICE', 'Receipt provenance changed');
      for (const hash of receipt.sourceHashes)
        if (!raw.has(hash))
          throw new PoaError(
            'ARCHIVE_INTEGRITY',
            'Missing exact diagnostic input',
          );
      const source = raw.get(receipt.sourceHashes[0]!) as any;
      const costs = 'costs' in receipt ? receipt.costs : [];
      if (
        source.gasUsdcMinor !== null &&
        (costs.length !== 1 ||
          costs[0]!.amountUsdcMinor !== source.gasUsdcMinor ||
          costs[0]!.sourceHash !== receipt.sourceHashes[0])
      )
        throw new PoaError(
          'REPLAY_MISMATCH',
          'Diagnostic cost differs from its exact source',
        );
      if (
        source.operationId !== receipt.operationId ||
        source.scenarioId !== state.scenarioId ||
        source.observedAt !== receipt.observedAt ||
        source.sourceProvenance !== 'SYNTHETIC_TEST'
      )
        throw new PoaError(
          'PROVENANCE_SPLICE',
          'Receipt source is outside its financial identity',
        );
      for (const [key, value] of Object.entries(source.fields))
        if (contentHash((receipt as any)[key]) !== contentHash(value))
          throw new PoaError(
            'REPLAY_MISMATCH',
            'Receipt differs from exact captured mechanics',
          );
      state = applyReceipt(JSON.parse(JSON.stringify(state)), receipt);
      // Duplicate delivery after serialization must be an exact no-op.
      if (contentHash(applyReceipt(state, receipt)) !== contentHash(state))
        throw new PoaError('REPLAY_MISMATCH', 'Duplicate financial effect');
      snapshots.push({ at: receipt.observedAt, portfolio: state });
    }
    if (contentHash(state) !== scenario.expectedFinalHash)
      throw new PoaError('REPLAY_MISMATCH', 'Diagnostic final state changed');
    const deadline = snapshots.find((s) => s.portfolio.closedAt !== null);
    let peak = BigInt(state.initialValueUsdcMinor),
      drawdown = 0n;
    for (const snapshot of snapshots) {
      const value = BigInt(globalBookValue(snapshot.portfolio));
      if (value > peak) peak = value;
      const draw = ((peak - value) * 10000n) / peak;
      if (draw > drawdown) drawdown = draw;
    }
    if (new Set(scenario.references.map((r) => r.kind)).size !== 2)
      throw new PoaError(
        'REPLAY_MISMATCH',
        'Exactly two frozen references are required',
      );
    const references = scenario.references.map((reference) => {
      if (
        reference.initial.initialValueUsdcMinor !==
          scenario.initial.initialValueUsdcMinor ||
        contentHash(reference.initial.cash) !==
          contentHash(scenario.initial.cash) ||
        reference.initial.resultProvenance !== 'SYNTHETIC_TEST'
      )
        throw new PoaError(
          'PROVENANCE_SPLICE',
          'Reference initial capital, distribution or provenance differs',
        );
      let current = reference.initial;
      for (const receipt of reference.receipts) {
        for (const hash of receipt.sourceHashes)
          if (!raw.has(hash))
            throw new PoaError(
              'ARCHIVE_INTEGRITY',
              'Reference requires every cost and mechanics source',
            );
        const source = raw.get(receipt.sourceHashes[0]!) as any;
        if (
          !source ||
          source.operationId !== receipt.operationId ||
          source.scenarioId !== current.scenarioId
        )
          throw new PoaError(
            'ARCHIVE_INTEGRITY',
            'Reference source is missing or mismatched',
          );
        for (const [key, value] of Object.entries(source.fields))
          if (contentHash((receipt as any)[key]) !== contentHash(value))
            throw new PoaError(
              'REPLAY_MISMATCH',
              'Reference differs from captured mechanics',
            );
        current = applyReceipt(current, receipt);
      }
      if (contentHash(current) !== reference.expectedFinalHash)
        throw new PoaError('REPLAY_MISMATCH', 'Reference replay changed');
      return {
        kind: reference.kind,
        finalHash: contentHash(current),
        markValueUsdcMinor: globalBookValue(current),
        differenceUsdcMinor: (
          BigInt(globalBookValue(state)) - BigInt(globalBookValue(current))
        ).toString(),
      };
    });
    return {
      scenarioId: state.scenarioId,
      finalHash: contentHash(state),
      markValueUsdcMinor: globalBookValue(state),
      cashReferenceUsdcMinor: state.initialValueUsdcMinor,
      costsUsdcMinor: state.recognizedCosts
        .reduce((s, c) => s + BigInt(c.amountUsdcMinor), 0n)
        .toString(),
      maxDrawdownBps: drawdown.toString(),
      references,
      deadlineStateHash: state.deadlineStateHash,
      unresolvedAtClosure:
        deadline?.portfolio.receivables[0]?.amountUsdcMinor ?? null,
      unavailableMark: valuePortfolio(
        state,
        state.positions.map((p) => ({
          positionId: p.positionId,
          markValueUsdcMinor: null,
          recoverableUsdcMinor: null,
          exitCostUsdcMinor: null,
          dataQuality: 'UNAVAILABLE' as const,
          sourceHash: p.lastSourceHash,
          observedAt: p.lastObservedAt,
        })),
      ).markValueUsdcMinor,
      snapshots,
    };
  });
  return {
    diagnosticHash: contentHash(bundle),
    presentationProvenance: bundle.presentationProvenance,
    sourceProvenance: bundle.sourceProvenance,
    forwardObservationCount: '0',
    scenarios: output,
  };
}

import { mkdir, readFile, writeFile } from 'node:fs/promises';
import { dirname, join } from 'node:path';
import {
  canonicalJson,
  contentHash,
  PoaError,
  rawBytesHash,
} from '@poa/domain';
import {
  ArchivedObservation,
  type ArchivedObservationData,
  type RawObjectDescriptorData,
  SourceRef,
} from '@poa/schemas';

export interface ObjectArchive {
  putIfAbsent(key: string, bytes: Uint8Array): Promise<void>;
  get(key: string): Promise<Uint8Array | null>;
}

export class MemoryObjectArchive implements ObjectArchive {
  readonly objects = new Map<string, Uint8Array>();

  async putIfAbsent(key: string, bytes: Uint8Array) {
    const prior = this.objects.get(key);
    if (prior && !equal(prior, bytes))
      integrity(`Object key collision at ${key}`);
    if (!prior) this.objects.set(key, bytes.slice());
  }

  async get(key: string) {
    return this.objects.get(key)?.slice() ?? null;
  }
}

export class FileObjectArchive implements ObjectArchive {
  constructor(private readonly root: string) {}

  private path(key: string) {
    if (!/^raw\/keccak256\/0x[0-9a-f]{64}$/.test(key))
      integrity(`Invalid content-addressed object key: ${key}`);
    return join(this.root, key);
  }

  async putIfAbsent(key: string, bytes: Uint8Array) {
    const path = this.path(key);
    await mkdir(dirname(path), { recursive: true });
    try {
      await writeFile(path, bytes, { flag: 'wx' });
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code !== 'EEXIST') throw error;
      const prior = await readFile(path);
      if (!equal(prior, bytes)) integrity(`Object key collision at ${key}`);
    }
  }

  async get(key: string) {
    try {
      return new Uint8Array(await readFile(this.path(key)));
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code === 'ENOENT') return null;
      throw error;
    }
  }
}

// Production supplies a credentialed S3-compatible driver. Keeping this small
// interface makes retention/restore tests possible without embedding credentials
// or treating a successful PUT as evidence that retention is configured.
export interface S3CompatibleDriver {
  putObjectIfAbsent(key: string, bytes: Uint8Array): Promise<void>;
  getObject(key: string): Promise<Uint8Array | null>;
}

export class S3CompatibleObjectArchive implements ObjectArchive {
  constructor(private readonly driver: S3CompatibleDriver) {}
  putIfAbsent(key: string, bytes: Uint8Array) {
    return this.driver.putObjectIfAbsent(key, bytes);
  }
  get(key: string) {
    return this.driver.getObject(key);
  }
}

function equal(a: Uint8Array, b: Uint8Array) {
  return a.length === b.length && a.every((value, index) => value === b[index]);
}
function integrity(message: string): never {
  throw new PoaError('ARCHIVE_INTEGRITY', message);
}

export async function archiveJson(
  archive: ObjectArchive,
  value: unknown,
  capturedAt: string,
): Promise<RawObjectDescriptorData> {
  const bytes = new TextEncoder().encode(canonicalJson(value));
  const objectHash = rawBytesHash(bytes);
  const objectKey = `raw/keccak256/${objectHash}`;
  await archive.putIfAbsent(objectKey, bytes);
  return {
    schemaVersion: 'proof-of-alpha/raw-object/v1',
    objectHash,
    objectKey,
    mediaType: 'application/json',
    contentLengthBytes: String(bytes.length),
    capturedAt,
  };
}

export async function archiveRawJsonBytes(
  archive: ObjectArchive,
  bytes: Uint8Array,
  capturedAt: string,
): Promise<RawObjectDescriptorData> {
  try {
    JSON.parse(new TextDecoder('utf-8', { fatal: true }).decode(bytes));
  } catch {
    integrity('Raw object is not valid JSON');
  }
  const objectHash = rawBytesHash(bytes);
  const objectKey = `raw/keccak256/${objectHash}`;
  await archive.putIfAbsent(objectKey, bytes);
  return {
    schemaVersion: 'proof-of-alpha/raw-object/v1',
    objectHash,
    objectKey,
    mediaType: 'application/json',
    contentLengthBytes: String(bytes.length),
    capturedAt,
  };
}

export async function readArchivedJson(
  archive: ObjectArchive,
  descriptor: RawObjectDescriptorData,
): Promise<unknown> {
  const bytes = await archive.get(descriptor.objectKey);
  if (!bytes)
    throw new PoaError(
      'DATA_UNAVAILABLE',
      `Archived object missing: ${descriptor.objectHash}`,
    );
  if (String(bytes.length) !== descriptor.contentLengthBytes)
    integrity(`Archived byte length differs for ${descriptor.objectHash}`);
  if (rawBytesHash(bytes) !== descriptor.objectHash)
    integrity(`Archived content hash differs for ${descriptor.objectHash}`);
  try {
    return JSON.parse(new TextDecoder().decode(bytes));
  } catch {
    integrity(`Archived JSON is invalid for ${descriptor.objectHash}`);
  }
}

export function createObservation(
  input: Omit<ArchivedObservationData, 'schemaVersion'>,
): ArchivedObservationData {
  return ArchivedObservation.parse({
    schemaVersion: 'proof-of-alpha/archived-observation/v1',
    ...input,
  });
}

export function requireFresh(
  observation: ArchivedObservationData,
  evaluationTime: string,
) {
  const parsed = ArchivedObservation.parse(observation);
  if (evaluationTime < parsed.observedAt || evaluationTime >= parsed.expiresAt)
    throw new PoaError(
      'DATA_STALE',
      `Observation ${parsed.observationId} is outside its validity interval`,
    );
  return parsed;
}

export function toSourceRef(
  observation: ArchivedObservationData,
  evaluationTime: string,
) {
  const fresh = requireFresh(observation, evaluationTime);
  return SourceRef.parse({
    sourceId: fresh.sourceId,
    sourceVersion: fresh.sourceVersion,
    requestedAt: fresh.requestedAt,
    observedAt: fresh.observedAt,
    block: fresh.block,
    rawObjectHash: fresh.rawObject.objectHash,
    parserVersion: fresh.parserVersion,
    adapterVersion: fresh.adapterVersion,
    freshness: 'FRESH',
    resultProvenance: fresh.resultProvenance,
  });
}

export const observationSourceHash = (refs: ReturnType<typeof toSourceRef>[]) =>
  contentHash({ schemaVersion: 'proof-of-alpha/adapter-sources/v1', refs });

