  .strictObject({
    schemaVersion: z.literal('proof-of-alpha/transfer-receipt/v1'),
    experimentId: Id,
    scenarioId: Id,
    transferId: Id,
    state: z.enum(TRANSFER_STATES),
    resultProvenance: Provenance,
    executionMode: z.enum(['SIMULATED', 'ACTUAL_TESTNET']),
