      ctx.addIssue({
        code: 'custom',
        message: 'Unsettled transfer cannot claim a destination credit',
      });
    if (
      r.state === 'SETTLED' &&
      (r.netReceivableUsdcMinor !== '0' ||
        (r.executionMode === 'ACTUAL_TESTNET' &&
          (!r.messageHash ||
            !r.sourceTransactionHash ||
            !r.destinationTransactionHash ||
